/* Original educational practice prompts; not licensed NCBE exam items. */
window.BAR_QUESTIONS = [{"id":"CP-01-A","subject":"Civil Procedure","topic":"Diversity jurisdiction","type":"application","question":"A New York citizen sues a New Jersey citizen for $90,000 on a state-law contract claim in federal court. Which doctrine supports jurisdiction?","options":["General personal jurisdiction","Diversity jurisdiction","Personal jurisdiction waiver","Removal deadline"],"answer":1,"explanation":"Diversity jurisdiction: Complete diversity and more than $75,000 in controversy ordinarily support federal diversity jurisdiction."},{"id":"CP-01-B","subject":"Civil Procedure","topic":"Diversity jurisdiction","type":"rule","question":"Which statement correctly describes Diversity jurisdiction?","options":["Individuals are generally subject to general personal jurisdiction in their state of domicile.","The ordinary deadline to remove is 30 days after receiving the pleading that first establishes removability.","Complete diversity and more than $75,000 in controversy ordinarily support federal diversity jurisdiction.","A personal-jurisdiction defense is generally waived if omitted from the required initial Rule 12 response."],"answer":2,"explanation":"Diversity jurisdiction: Complete diversity and more than $75,000 in controversy ordinarily support federal diversity jurisdiction."},{"id":"CP-02-A","subject":"Civil Procedure","topic":"Complete diversity","type":"application","question":"An Ohio plaintiff sues defendants from Ohio and Michigan on a state tort claim. Which doctrine defeats diversity?","options":["Complete diversity","Diversity jurisdiction","Supplemental jurisdiction","Summary judgment"],"answer":0,"explanation":"Complete diversity: No plaintiff may share state citizenship with any opposing defendant for complete diversity."},{"id":"CP-02-B","subject":"Civil Procedure","topic":"Complete diversity","type":"rule","question":"Which statement correctly describes Complete diversity?","options":["Complete diversity and more than $75,000 in controversy ordinarily support federal diversity jurisdiction.","Rule 56 allows summary judgment when no genuine dispute of material fact exists and movant wins as a matter of law.","No plaintiff may share state citizenship with any opposing defendant for complete diversity.","Related claims sharing a common nucleus of operative fact may be heard under supplemental jurisdiction."],"answer":2,"explanation":"Complete diversity: No plaintiff may share state citizenship with any opposing defendant for complete diversity."},{"id":"CP-03-A","subject":"Civil Procedure","topic":"Well-pleaded complaint rule","type":"application","question":"A state-law negligence complaint merely anticipates a federal statutory defense. What rule prevents federal-question jurisdiction?","options":["Specific personal jurisdiction","Supplemental jurisdiction","Well-pleaded complaint rule","Compulsory counterclaim"],"answer":2,"explanation":"Well-pleaded complaint rule: A federal question normally must appear on the face of the plaintiff's properly pleaded claim, not merely in a defense."},{"id":"CP-03-B","subject":"Civil Procedure","topic":"Well-pleaded complaint rule","type":"rule","question":"Which statement correctly describes Well-pleaded complaint rule?","options":["Rule 13(a) generally requires a counterclaim arising from the same transaction or occurrence, subject to exceptions.","A federal question normally must appear on the face of the plaintiff's properly pleaded claim, not merely in a defense.","Related claims sharing a common nucleus of operative fact may be heard under supplemental jurisdiction.","Specific jurisdiction generally requires purposeful forum contacts related to the lawsuit and fairness."],"answer":1,"explanation":"Well-pleaded complaint rule: A federal question normally must appear on the face of the plaintiff's properly pleaded claim, not merely in a defense."},{"id":"CP-04-A","subject":"Civil Procedure","topic":"Removal deadline","type":"application","question":"A defendant receives a pleading first showing the case is removable and wants federal court. Which timing rule governs?","options":["Removal deadline","Erie and Hanna doctrine","Claim preclusion","Class numerosity"],"answer":0,"explanation":"Removal deadline: The ordinary deadline to remove is 30 days after receiving the pleading that first establishes removability."},{"id":"CP-04-B","subject":"Civil Procedure","topic":"Removal deadline","type":"rule","question":"Which statement correctly describes Removal deadline?","options":["Numerosity requires a sufficiently numerous class that joining all members is impracticable.","The ordinary deadline to remove is 30 days after receiving the pleading that first establishes removability.","Claim preclusion generally bars the same claim between the same parties or privies after a valid final merits judgment.","A valid on-point Federal Rule generally applies in federal court, including diversity cases."],"answer":1,"explanation":"Removal deadline: The ordinary deadline to remove is 30 days after receiving the pleading that first establishes removability."},{"id":"CP-05-A","subject":"Civil Procedure","topic":"Forum-defendant rule","type":"application","question":"A Texas defendant is sued in Texas state court and removal would rest solely on diversity. What rule normally blocks removal?","options":["General personal jurisdiction","Forum-defendant rule","Removal deadline","Erie and Hanna doctrine"],"answer":1,"explanation":"Forum-defendant rule: A properly joined and served forum-state defendant ordinarily cannot remove on diversity grounds alone."},{"id":"CP-05-B","subject":"Civil Procedure","topic":"Forum-defendant rule","type":"rule","question":"Which statement correctly describes Forum-defendant rule?","options":["Individuals are generally subject to general personal jurisdiction in their state of domicile.","A properly joined and served forum-state defendant ordinarily cannot remove on diversity grounds alone.","The ordinary deadline to remove is 30 days after receiving the pleading that first establishes removability.","A valid on-point Federal Rule generally applies in federal court, including diversity cases."],"answer":1,"explanation":"Forum-defendant rule: A properly joined and served forum-state defendant ordinarily cannot remove on diversity grounds alone."},{"id":"CP-06-A","subject":"Civil Procedure","topic":"Supplemental jurisdiction","type":"application","question":"A state negligence claim and a federal civil-rights claim arise from the same encounter. What allows both in federal court?","options":["Supplemental jurisdiction","Venue based on events","Erie and Hanna doctrine","Plausibility pleading"],"answer":0,"explanation":"Supplemental jurisdiction: Related claims sharing a common nucleus of operative fact may be heard under supplemental jurisdiction."},{"id":"CP-06-B","subject":"Civil Procedure","topic":"Supplemental jurisdiction","type":"rule","question":"Which statement correctly describes Supplemental jurisdiction?","options":["A valid on-point Federal Rule generally applies in federal court, including diversity cases.","Venue may lie where a substantial part of the events or omissions giving rise to the claim occurred.","Related claims sharing a common nucleus of operative fact may be heard under supplemental jurisdiction.","Rule 12(b)(6) requires sufficient factual allegations to make a claim plausible, not mere legal conclusions."],"answer":2,"explanation":"Supplemental jurisdiction: Related claims sharing a common nucleus of operative fact may be heard under supplemental jurisdiction."},{"id":"CP-07-A","subject":"Civil Procedure","topic":"Erie and Hanna doctrine","type":"application","question":"A valid Federal Rule directly controls a procedure in a diversity case despite different state procedure. Which doctrine governs?","options":["Erie and Hanna doctrine","Complete diversity","Forum-defendant rule","Summary judgment"],"answer":0,"explanation":"Erie and Hanna doctrine: A valid on-point Federal Rule generally applies in federal court, including diversity cases."},{"id":"CP-07-B","subject":"Civil Procedure","topic":"Erie and Hanna doctrine","type":"rule","question":"Which statement correctly describes Erie and Hanna doctrine?","options":["Rule 56 allows summary judgment when no genuine dispute of material fact exists and movant wins as a matter of law.","A valid on-point Federal Rule generally applies in federal court, including diversity cases.","No plaintiff may share state citizenship with any opposing defendant for complete diversity.","A properly joined and served forum-state defendant ordinarily cannot remove on diversity grounds alone."],"answer":1,"explanation":"Erie and Hanna doctrine: A valid on-point Federal Rule generally applies in federal court, including diversity cases."},{"id":"CP-08-A","subject":"Civil Procedure","topic":"Specific personal jurisdiction","type":"application","question":"A seller purposefully targets a state's residents and is sued about a sale there. Which kind of jurisdiction is relevant?","options":["Specific personal jurisdiction","Claim preclusion","Work-product protection","Section 1404 transfer"],"answer":0,"explanation":"Specific personal jurisdiction: Specific jurisdiction generally requires purposeful forum contacts related to the lawsuit and fairness."},{"id":"CP-08-B","subject":"Civil Procedure","topic":"Specific personal jurisdiction","type":"rule","question":"Which statement correctly describes Specific personal jurisdiction?","options":["Specific jurisdiction generally requires purposeful forum contacts related to the lawsuit and fairness.","Claim preclusion generally bars the same claim between the same parties or privies after a valid final merits judgment.","Materials prepared in anticipation of litigation receive qualified protection, with special protection for mental impressions.","A court may transfer venue under 28 U.S.C. § 1404(a) for convenience and in the interest of justice."],"answer":0,"explanation":"Specific personal jurisdiction: Specific jurisdiction generally requires purposeful forum contacts related to the lawsuit and fairness."},{"id":"CP-09-A","subject":"Civil Procedure","topic":"General personal jurisdiction","type":"application","question":"An individual is permanently domiciled in Oregon but briefly visits Nevada. Which theory permits unrelated claims in Oregon?","options":["General personal jurisdiction","Compulsory counterclaim","Plausibility pleading","Removal deadline"],"answer":0,"explanation":"General personal jurisdiction: Individuals are generally subject to general personal jurisdiction in their state of domicile."},{"id":"CP-09-B","subject":"Civil Procedure","topic":"General personal jurisdiction","type":"rule","question":"Which statement correctly describes General personal jurisdiction?","options":["Rule 12(b)(6) requires sufficient factual allegations to make a claim plausible, not mere legal conclusions.","The ordinary deadline to remove is 30 days after receiving the pleading that first establishes removability.","Individuals are generally subject to general personal jurisdiction in their state of domicile.","Rule 13(a) generally requires a counterclaim arising from the same transaction or occurrence, subject to exceptions."],"answer":2,"explanation":"General personal jurisdiction: Individuals are generally subject to general personal jurisdiction in their state of domicile."},{"id":"CP-10-A","subject":"Civil Procedure","topic":"Service deadline","type":"application","question":"A plaintiff files a federal complaint but does not serve the defendant for 90 days. What rule is implicated?","options":["Erie and Hanna doctrine","Service deadline","Plausibility pleading","Diversity jurisdiction"],"answer":1,"explanation":"Service deadline: Rule 4(m) generally calls for service within 90 days, subject to exceptions and extensions."},{"id":"CP-10-B","subject":"Civil Procedure","topic":"Service deadline","type":"rule","question":"Which statement correctly describes Service deadline?","options":["Rule 4(m) generally calls for service within 90 days, subject to exceptions and extensions.","Rule 12(b)(6) requires sufficient factual allegations to make a claim plausible, not mere legal conclusions.","A valid on-point Federal Rule generally applies in federal court, including diversity cases.","Complete diversity and more than $75,000 in controversy ordinarily support federal diversity jurisdiction."],"answer":0,"explanation":"Service deadline: Rule 4(m) generally calls for service within 90 days, subject to exceptions and extensions."},{"id":"CP-11-A","subject":"Civil Procedure","topic":"Venue based on events","type":"application","question":"A substantial portion of the events occurred in a particular federal district. What makes venue proper there?","options":["General personal jurisdiction","Venue based on events","Forum-defendant rule","Compulsory counterclaim"],"answer":1,"explanation":"Venue based on events: Venue may lie where a substantial part of the events or omissions giving rise to the claim occurred."},{"id":"CP-11-B","subject":"Civil Procedure","topic":"Venue based on events","type":"rule","question":"Which statement correctly describes Venue based on events?","options":["Rule 13(a) generally requires a counterclaim arising from the same transaction or occurrence, subject to exceptions.","A properly joined and served forum-state defendant ordinarily cannot remove on diversity grounds alone.","Individuals are generally subject to general personal jurisdiction in their state of domicile.","Venue may lie where a substantial part of the events or omissions giving rise to the claim occurred."],"answer":3,"explanation":"Venue based on events: Venue may lie where a substantial part of the events or omissions giving rise to the claim occurred."},{"id":"CP-12-A","subject":"Civil Procedure","topic":"Section 1404 transfer","type":"application","question":"Witnesses and documents are located in another district where the case could have been filed. Which procedure fits?","options":["Supplemental jurisdiction","Plausibility pleading","Summary judgment","Section 1404 transfer"],"answer":3,"explanation":"Section 1404 transfer: A court may transfer venue under 28 U.S.C. § 1404(a) for convenience and in the interest of justice."},{"id":"CP-12-B","subject":"Civil Procedure","topic":"Section 1404 transfer","type":"rule","question":"Which statement correctly describes Section 1404 transfer?","options":["Related claims sharing a common nucleus of operative fact may be heard under supplemental jurisdiction.","Rule 12(b)(6) requires sufficient factual allegations to make a claim plausible, not mere legal conclusions.","A court may transfer venue under 28 U.S.C. § 1404(a) for convenience and in the interest of justice.","Rule 56 allows summary judgment when no genuine dispute of material fact exists and movant wins as a matter of law."],"answer":2,"explanation":"Section 1404 transfer: A court may transfer venue under 28 U.S.C. § 1404(a) for convenience and in the interest of justice."},{"id":"CP-13-A","subject":"Civil Procedure","topic":"Claim preclusion","type":"application","question":"Parties try to relitigate the same claim after a valid final judgment on the merits. What bars the case?","options":["General personal jurisdiction","Claim preclusion","Supplemental jurisdiction","Compulsory counterclaim"],"answer":1,"explanation":"Claim preclusion: Claim preclusion generally bars the same claim between the same parties or privies after a valid final merits judgment."},{"id":"CP-13-B","subject":"Civil Procedure","topic":"Claim preclusion","type":"rule","question":"Which statement correctly describes Claim preclusion?","options":["Rule 13(a) generally requires a counterclaim arising from the same transaction or occurrence, subject to exceptions.","Related claims sharing a common nucleus of operative fact may be heard under supplemental jurisdiction.","Individuals are generally subject to general personal jurisdiction in their state of domicile.","Claim preclusion generally bars the same claim between the same parties or privies after a valid final merits judgment."],"answer":3,"explanation":"Claim preclusion: Claim preclusion generally bars the same claim between the same parties or privies after a valid final merits judgment."},{"id":"CP-14-A","subject":"Civil Procedure","topic":"Issue preclusion","type":"application","question":"An essential factual issue was actually litigated and decided in a prior valid judgment. What doctrine bars relitigation?","options":["Section 1404 transfer","Plausibility pleading","Issue preclusion","Removal deadline"],"answer":2,"explanation":"Issue preclusion: Issue preclusion may bar an issue actually litigated, necessarily decided, and essential to a prior valid final judgment."},{"id":"CP-14-B","subject":"Civil Procedure","topic":"Issue preclusion","type":"rule","question":"Which statement correctly describes Issue preclusion?","options":["The ordinary deadline to remove is 30 days after receiving the pleading that first establishes removability.","Issue preclusion may bar an issue actually litigated, necessarily decided, and essential to a prior valid final judgment.","Rule 12(b)(6) requires sufficient factual allegations to make a claim plausible, not mere legal conclusions.","A court may transfer venue under 28 U.S.C. § 1404(a) for convenience and in the interest of justice."],"answer":1,"explanation":"Issue preclusion: Issue preclusion may bar an issue actually litigated, necessarily decided, and essential to a prior valid final judgment."},{"id":"CP-15-A","subject":"Civil Procedure","topic":"Summary judgment","type":"application","question":"After discovery, no genuine dispute of material fact remains and one side is entitled to judgment as law. Which motion fits?","options":["Summary judgment","Removal deadline","Plausibility pleading","Personal jurisdiction waiver"],"answer":0,"explanation":"Summary judgment: Rule 56 allows summary judgment when no genuine dispute of material fact exists and movant wins as a matter of law."},{"id":"CP-15-B","subject":"Civil Procedure","topic":"Summary judgment","type":"rule","question":"Which statement correctly describes Summary judgment?","options":["The ordinary deadline to remove is 30 days after receiving the pleading that first establishes removability.","Rule 56 allows summary judgment when no genuine dispute of material fact exists and movant wins as a matter of law.","Rule 12(b)(6) requires sufficient factual allegations to make a claim plausible, not mere legal conclusions.","A personal-jurisdiction defense is generally waived if omitted from the required initial Rule 12 response."],"answer":1,"explanation":"Summary judgment: Rule 56 allows summary judgment when no genuine dispute of material fact exists and movant wins as a matter of law."},{"id":"CP-16-A","subject":"Civil Procedure","topic":"Plausibility pleading","type":"application","question":"A complaint offers only labels and conclusions about negligence, without supporting facts. What pleading standard applies?","options":["Section 1404 transfer","Plausibility pleading","Issue preclusion","Erie and Hanna doctrine"],"answer":1,"explanation":"Plausibility pleading: Rule 12(b)(6) requires sufficient factual allegations to make a claim plausible, not mere legal conclusions."},{"id":"CP-16-B","subject":"Civil Procedure","topic":"Plausibility pleading","type":"rule","question":"Which statement correctly describes Plausibility pleading?","options":["Issue preclusion may bar an issue actually litigated, necessarily decided, and essential to a prior valid final judgment.","Rule 12(b)(6) requires sufficient factual allegations to make a claim plausible, not mere legal conclusions.","A court may transfer venue under 28 U.S.C. § 1404(a) for convenience and in the interest of justice.","A valid on-point Federal Rule generally applies in federal court, including diversity cases."],"answer":1,"explanation":"Plausibility pleading: Rule 12(b)(6) requires sufficient factual allegations to make a claim plausible, not mere legal conclusions."},{"id":"CP-17-A","subject":"Civil Procedure","topic":"Personal jurisdiction waiver","type":"application","question":"A defendant omits a personal-jurisdiction objection from the first Rule 12 motion. What rule is implicated?","options":["Class numerosity","General personal jurisdiction","Personal jurisdiction waiver","Compulsory counterclaim"],"answer":2,"explanation":"Personal jurisdiction waiver: A personal-jurisdiction defense is generally waived if omitted from the required initial Rule 12 response."},{"id":"CP-17-B","subject":"Civil Procedure","topic":"Personal jurisdiction waiver","type":"rule","question":"Which statement correctly describes Personal jurisdiction waiver?","options":["Rule 13(a) generally requires a counterclaim arising from the same transaction or occurrence, subject to exceptions.","A personal-jurisdiction defense is generally waived if omitted from the required initial Rule 12 response.","Individuals are generally subject to general personal jurisdiction in their state of domicile.","Numerosity requires a sufficiently numerous class that joining all members is impracticable."],"answer":1,"explanation":"Personal jurisdiction waiver: A personal-jurisdiction defense is generally waived if omitted from the required initial Rule 12 response."},{"id":"CP-18-A","subject":"Civil Procedure","topic":"Compulsory counterclaim","type":"application","question":"A defendant's claim against the plaintiff arises from the same transaction as the lawsuit. What is it called?","options":["General personal jurisdiction","Specific personal jurisdiction","Compulsory counterclaim","Removal deadline"],"answer":2,"explanation":"Compulsory counterclaim: Rule 13(a) generally requires a counterclaim arising from the same transaction or occurrence, subject to exceptions."},{"id":"CP-18-B","subject":"Civil Procedure","topic":"Compulsory counterclaim","type":"rule","question":"Which statement correctly describes Compulsory counterclaim?","options":["The ordinary deadline to remove is 30 days after receiving the pleading that first establishes removability.","Individuals are generally subject to general personal jurisdiction in their state of domicile.","Rule 13(a) generally requires a counterclaim arising from the same transaction or occurrence, subject to exceptions.","Specific jurisdiction generally requires purposeful forum contacts related to the lawsuit and fairness."],"answer":2,"explanation":"Compulsory counterclaim: Rule 13(a) generally requires a counterclaim arising from the same transaction or occurrence, subject to exceptions."},{"id":"CP-19-A","subject":"Civil Procedure","topic":"Work-product protection","type":"application","question":"A lawyer writes litigation strategy notes in anticipation of a lawsuit. What doctrine protects the notes?","options":["Complete diversity","Work-product protection","General personal jurisdiction","Compulsory counterclaim"],"answer":1,"explanation":"Work-product protection: Materials prepared in anticipation of litigation receive qualified protection, with special protection for mental impressions."},{"id":"CP-19-B","subject":"Civil Procedure","topic":"Work-product protection","type":"rule","question":"Which statement correctly describes Work-product protection?","options":["Rule 13(a) generally requires a counterclaim arising from the same transaction or occurrence, subject to exceptions.","Materials prepared in anticipation of litigation receive qualified protection, with special protection for mental impressions.","Individuals are generally subject to general personal jurisdiction in their state of domicile.","No plaintiff may share state citizenship with any opposing defendant for complete diversity."],"answer":1,"explanation":"Work-product protection: Materials prepared in anticipation of litigation receive qualified protection, with special protection for mental impressions."},{"id":"CP-20-A","subject":"Civil Procedure","topic":"Class numerosity","type":"application","question":"Hundreds of dispersed people share a common grievance, making joinder impracticable. Which Rule 23 requirement is shown?","options":["Class numerosity","Issue preclusion","Section 1404 transfer","Work-product protection"],"answer":0,"explanation":"Class numerosity: Numerosity requires a sufficiently numerous class that joining all members is impracticable."},{"id":"CP-20-B","subject":"Civil Procedure","topic":"Class numerosity","type":"rule","question":"Which statement correctly describes Class numerosity?","options":["Numerosity requires a sufficiently numerous class that joining all members is impracticable.","A court may transfer venue under 28 U.S.C. § 1404(a) for convenience and in the interest of justice.","Materials prepared in anticipation of litigation receive qualified protection, with special protection for mental impressions.","Issue preclusion may bar an issue actually litigated, necessarily decided, and essential to a prior valid final judgment."],"answer":0,"explanation":"Class numerosity: Numerosity requires a sufficiently numerous class that joining all members is impracticable."},{"id":"CL-01-A","subject":"Constitutional Law","topic":"State action doctrine","type":"application","question":"A private shop excludes a customer for a political view without any governmental involvement. What limits a constitutional free-speech claim?","options":["State action doctrine","Time-place-manner regulation","Intermediate scrutiny for sex","Viewpoint discrimination"],"answer":0,"explanation":"State action doctrine: Many constitutional rights constrain government conduct rather than purely private action."},{"id":"CL-01-B","subject":"Constitutional Law","topic":"State action doctrine","type":"rule","question":"Which statement correctly describes State action doctrine?","options":["Content-neutral time, place, and manner limits must be appropriately tailored and leave adequate alternatives.","Many constitutional rights constrain government conduct rather than purely private action.","Sex-based classifications ordinarily require an important governmental objective and a substantial relationship.","Government may not ordinarily favor a viewpoint over its opposing viewpoint in a public forum."],"answer":1,"explanation":"State action doctrine: Many constitutional rights constrain government conduct rather than purely private action."},{"id":"CL-02-A","subject":"Constitutional Law","topic":"Commerce Clause aggregation","type":"application","question":"Congress regulates homegrown wheat as part of a broader interstate wheat market regulation. Which power supports it?","options":["Free Exercise neutral law","True threats","Article III standing","Commerce Clause aggregation"],"answer":3,"explanation":"Commerce Clause aggregation: Congress may regulate local economic activity whose aggregate effect substantially affects interstate commerce."},{"id":"CL-02-B","subject":"Constitutional Law","topic":"Commerce Clause aggregation","type":"rule","question":"Which statement correctly describes Commerce Clause aggregation?","options":["Congress may regulate local economic activity whose aggregate effect substantially affects interstate commerce.","True threats constitute a limited category of speech that may be punished within constitutional requirements.","Federal standing generally requires injury in fact, causation, and likely redressability.","Neutral, generally applicable laws usually do not violate Free Exercise merely because they incidentally burden religion."],"answer":0,"explanation":"Commerce Clause aggregation: Congress may regulate local economic activity whose aggregate effect substantially affects interstate commerce."},{"id":"CL-03-A","subject":"Constitutional Law","topic":"Dormant Commerce Clause discrimination","type":"application","question":"A state taxes imported products more heavily than identical local products. What issue arises?","options":["Commerce Clause aggregation","State action doctrine","Dormant Commerce Clause discrimination","Spending Clause conditions"],"answer":2,"explanation":"Dormant Commerce Clause discrimination: Facially discriminatory state laws burdening interstate commerce receive especially demanding review."},{"id":"CL-03-B","subject":"Constitutional Law","topic":"Dormant Commerce Clause discrimination","type":"rule","question":"Which statement correctly describes Dormant Commerce Clause discrimination?","options":["Congress may attach clear, related, noncoercive conditions to federal spending, within constitutional limits.","Many constitutional rights constrain government conduct rather than purely private action.","Congress may regulate local economic activity whose aggregate effect substantially affects interstate commerce.","Facially discriminatory state laws burdening interstate commerce receive especially demanding review."],"answer":3,"explanation":"Dormant Commerce Clause discrimination: Facially discriminatory state laws burdening interstate commerce receive especially demanding review."},{"id":"CL-04-A","subject":"Constitutional Law","topic":"Spending Clause conditions","type":"application","question":"Congress offers transportation grants if states adopt related safety rules. Which power permits encouragement?","options":["Time-place-manner regulation","State action doctrine","Spending Clause conditions","Rational-basis review"],"answer":2,"explanation":"Spending Clause conditions: Congress may attach clear, related, noncoercive conditions to federal spending, within constitutional limits."},{"id":"CL-04-B","subject":"Constitutional Law","topic":"Spending Clause conditions","type":"rule","question":"Which statement correctly describes Spending Clause conditions?","options":["Content-neutral time, place, and manner limits must be appropriately tailored and leave adequate alternatives.","Ordinary economic regulation generally needs a rational relation to a legitimate government purpose.","Many constitutional rights constrain government conduct rather than purely private action.","Congress may attach clear, related, noncoercive conditions to federal spending, within constitutional limits."],"answer":3,"explanation":"Spending Clause conditions: Congress may attach clear, related, noncoercive conditions to federal spending, within constitutional limits."},{"id":"CL-05-A","subject":"Constitutional Law","topic":"Anti-commandeering principle","type":"application","question":"Congress commands state legislatures to enact a federal program. What constitutional limit applies?","options":["Article III standing","Spending Clause conditions","Anti-commandeering principle","Procedural due process"],"answer":2,"explanation":"Anti-commandeering principle: Congress ordinarily may not directly command state governments to legislate or administer federal programs."},{"id":"CL-05-B","subject":"Constitutional Law","topic":"Anti-commandeering principle","type":"rule","question":"Which statement correctly describes Anti-commandeering principle?","options":["Government deprivation of protected life, liberty, or property interests ordinarily requires constitutionally appropriate process.","Congress may attach clear, related, noncoercive conditions to federal spending, within constitutional limits.","Federal standing generally requires injury in fact, causation, and likely redressability.","Congress ordinarily may not directly command state governments to legislate or administer federal programs."],"answer":3,"explanation":"Anti-commandeering principle: Congress ordinarily may not directly command state governments to legislate or administer federal programs."},{"id":"CL-06-A","subject":"Constitutional Law","topic":"Strict scrutiny for race","type":"application","question":"A public university classifies students explicitly by race. Which equal-protection standard applies?","options":["Strict scrutiny for race","Free Exercise neutral law","Spending Clause conditions","State action doctrine"],"answer":0,"explanation":"Strict scrutiny for race: Government racial classifications face strict scrutiny requiring a compelling interest and narrow tailoring."},{"id":"CL-06-B","subject":"Constitutional Law","topic":"Strict scrutiny for race","type":"rule","question":"Which statement correctly describes Strict scrutiny for race?","options":["Neutral, generally applicable laws usually do not violate Free Exercise merely because they incidentally burden religion.","Government racial classifications face strict scrutiny requiring a compelling interest and narrow tailoring.","Many constitutional rights constrain government conduct rather than purely private action.","Congress may attach clear, related, noncoercive conditions to federal spending, within constitutional limits."],"answer":1,"explanation":"Strict scrutiny for race: Government racial classifications face strict scrutiny requiring a compelling interest and narrow tailoring."},{"id":"CL-07-A","subject":"Constitutional Law","topic":"Intermediate scrutiny for sex","type":"application","question":"A state uses different permit rules for men and women. Which review standard generally applies?","options":["Intermediate scrutiny for sex","Free Exercise neutral law","Incitement standard","Time-place-manner regulation"],"answer":0,"explanation":"Intermediate scrutiny for sex: Sex-based classifications ordinarily require an important governmental objective and a substantial relationship."},{"id":"CL-07-B","subject":"Constitutional Law","topic":"Intermediate scrutiny for sex","type":"rule","question":"Which statement correctly describes Intermediate scrutiny for sex?","options":["Neutral, generally applicable laws usually do not violate Free Exercise merely because they incidentally burden religion.","Content-neutral time, place, and manner limits must be appropriately tailored and leave adequate alternatives.","Sex-based classifications ordinarily require an important governmental objective and a substantial relationship.","Unprotected incitement requires advocacy intended and likely to produce imminent lawless action."],"answer":2,"explanation":"Intermediate scrutiny for sex: Sex-based classifications ordinarily require an important governmental objective and a substantial relationship."},{"id":"CL-08-A","subject":"Constitutional Law","topic":"Rational-basis review","type":"application","question":"A state creates an ordinary business licensing category not affecting suspect classes or fundamental rights. Which standard applies?","options":["Procedural due process","State action doctrine","Right to interstate travel","Rational-basis review"],"answer":3,"explanation":"Rational-basis review: Ordinary economic regulation generally needs a rational relation to a legitimate government purpose."},{"id":"CL-08-B","subject":"Constitutional Law","topic":"Rational-basis review","type":"rule","question":"Which statement correctly describes Rational-basis review?","options":["Government deprivation of protected life, liberty, or property interests ordinarily requires constitutionally appropriate process.","Ordinary economic regulation generally needs a rational relation to a legitimate government purpose.","The constitutional right to interstate travel protects movement and equal treatment of new residents.","Many constitutional rights constrain government conduct rather than purely private action."],"answer":1,"explanation":"Rational-basis review: Ordinary economic regulation generally needs a rational relation to a legitimate government purpose."},{"id":"CL-09-A","subject":"Constitutional Law","topic":"Right to interstate travel","type":"application","question":"A state withholds basic newcomer benefits solely because residents recently moved from another state. What right is implicated?","options":["Incitement standard","Supremacy Clause preemption","Anti-commandeering principle","Right to interstate travel"],"answer":3,"explanation":"Right to interstate travel: The constitutional right to interstate travel protects movement and equal treatment of new residents."},{"id":"CL-09-B","subject":"Constitutional Law","topic":"Right to interstate travel","type":"rule","question":"Which statement correctly describes Right to interstate travel?","options":["Congress ordinarily may not directly command state governments to legislate or administer federal programs.","Valid federal law displaces conflicting state law under the Supremacy Clause.","The constitutional right to interstate travel protects movement and equal treatment of new residents.","Unprotected incitement requires advocacy intended and likely to produce imminent lawless action."],"answer":2,"explanation":"Right to interstate travel: The constitutional right to interstate travel protects movement and equal treatment of new residents."},{"id":"CL-10-A","subject":"Constitutional Law","topic":"Procedural due process","type":"application","question":"A public worker with a protected employment interest is fired without meaningful notice or opportunity to respond. What doctrine applies?","options":["Supremacy Clause preemption","Incitement standard","Procedural due process","Ex post facto prohibition"],"answer":2,"explanation":"Procedural due process: Government deprivation of protected life, liberty, or property interests ordinarily requires constitutionally appropriate process."},{"id":"CL-10-B","subject":"Constitutional Law","topic":"Procedural due process","type":"rule","question":"Which statement correctly describes Procedural due process?","options":["The Ex Post Facto Clauses prohibit certain retroactive criminal laws, including criminalizing previously lawful conduct.","Government deprivation of protected life, liberty, or property interests ordinarily requires constitutionally appropriate process.","Unprotected incitement requires advocacy intended and likely to produce imminent lawless action.","Valid federal law displaces conflicting state law under the Supremacy Clause."],"answer":1,"explanation":"Procedural due process: Government deprivation of protected life, liberty, or property interests ordinarily requires constitutionally appropriate process."},{"id":"CL-11-A","subject":"Constitutional Law","topic":"Viewpoint discrimination","type":"application","question":"A city allows pro-mayor protests but bans anti-mayor protests in the same public park. Which speech restriction is involved?","options":["Spending Clause conditions","Ex post facto prohibition","Free Exercise neutral law","Viewpoint discrimination"],"answer":3,"explanation":"Viewpoint discrimination: Government may not ordinarily favor a viewpoint over its opposing viewpoint in a public forum."},{"id":"CL-11-B","subject":"Constitutional Law","topic":"Viewpoint discrimination","type":"rule","question":"Which statement correctly describes Viewpoint discrimination?","options":["Government may not ordinarily favor a viewpoint over its opposing viewpoint in a public forum.","Congress may attach clear, related, noncoercive conditions to federal spending, within constitutional limits.","Neutral, generally applicable laws usually do not violate Free Exercise merely because they incidentally burden religion.","The Ex Post Facto Clauses prohibit certain retroactive criminal laws, including criminalizing previously lawful conduct."],"answer":0,"explanation":"Viewpoint discrimination: Government may not ordinarily favor a viewpoint over its opposing viewpoint in a public forum."},{"id":"CL-12-A","subject":"Constitutional Law","topic":"Content-based speech restriction","type":"application","question":"A city bans signs specifically criticizing a named public policy. What First Amendment framework applies?","options":["Viewpoint discrimination","Ex post facto prohibition","Content-based speech restriction","Rational-basis review"],"answer":2,"explanation":"Content-based speech restriction: Content-based speech regulations generally receive strict scrutiny unless an established exception applies."},{"id":"CL-12-B","subject":"Constitutional Law","topic":"Content-based speech restriction","type":"rule","question":"Which statement correctly describes Content-based speech restriction?","options":["Ordinary economic regulation generally needs a rational relation to a legitimate government purpose.","Content-based speech regulations generally receive strict scrutiny unless an established exception applies.","Government may not ordinarily favor a viewpoint over its opposing viewpoint in a public forum.","The Ex Post Facto Clauses prohibit certain retroactive criminal laws, including criminalizing previously lawful conduct."],"answer":1,"explanation":"Content-based speech restriction: Content-based speech regulations generally receive strict scrutiny unless an established exception applies."},{"id":"CL-13-A","subject":"Constitutional Law","topic":"Time-place-manner regulation","type":"application","question":"A city limits nighttime noise in public parks without regard to a speaker's message. Which doctrine applies?","options":["Time-place-manner regulation","Supremacy Clause preemption","Free Exercise neutral law","Viewpoint discrimination"],"answer":0,"explanation":"Time-place-manner regulation: Content-neutral time, place, and manner limits must be appropriately tailored and leave adequate alternatives."},{"id":"CL-13-B","subject":"Constitutional Law","topic":"Time-place-manner regulation","type":"rule","question":"Which statement correctly describes Time-place-manner regulation?","options":["Content-neutral time, place, and manner limits must be appropriately tailored and leave adequate alternatives.","Valid federal law displaces conflicting state law under the Supremacy Clause.","Neutral, generally applicable laws usually do not violate Free Exercise merely because they incidentally burden religion.","Government may not ordinarily favor a viewpoint over its opposing viewpoint in a public forum."],"answer":0,"explanation":"Time-place-manner regulation: Content-neutral time, place, and manner limits must be appropriately tailored and leave adequate alternatives."},{"id":"CL-14-A","subject":"Constitutional Law","topic":"Incitement standard","type":"application","question":"A speaker advocates unspecified future lawbreaking but not imminent action. What doctrine protects the speech?","options":["Rational-basis review","Viewpoint discrimination","Incitement standard","Time-place-manner regulation"],"answer":2,"explanation":"Incitement standard: Unprotected incitement requires advocacy intended and likely to produce imminent lawless action."},{"id":"CL-14-B","subject":"Constitutional Law","topic":"Incitement standard","type":"rule","question":"Which statement correctly describes Incitement standard?","options":["Ordinary economic regulation generally needs a rational relation to a legitimate government purpose.","Content-neutral time, place, and manner limits must be appropriately tailored and leave adequate alternatives.","Government may not ordinarily favor a viewpoint over its opposing viewpoint in a public forum.","Unprotected incitement requires advocacy intended and likely to produce imminent lawless action."],"answer":3,"explanation":"Incitement standard: Unprotected incitement requires advocacy intended and likely to produce imminent lawless action."},{"id":"CL-15-A","subject":"Constitutional Law","topic":"True threats","type":"application","question":"A speaker seriously communicates intent to inflict unlawful physical violence on an identified person. What speech category applies?","options":["Dormant Commerce Clause discrimination","Content-based speech restriction","True threats","Takings Clause"],"answer":2,"explanation":"True threats: True threats constitute a limited category of speech that may be punished within constitutional requirements."},{"id":"CL-15-B","subject":"Constitutional Law","topic":"True threats","type":"rule","question":"Which statement correctly describes True threats?","options":["Content-based speech regulations generally receive strict scrutiny unless an established exception applies.","Facially discriminatory state laws burdening interstate commerce receive especially demanding review.","The Fifth Amendment Takings Clause requires public use and just compensation for covered government takings.","True threats constitute a limited category of speech that may be punished within constitutional requirements."],"answer":3,"explanation":"True threats: True threats constitute a limited category of speech that may be punished within constitutional requirements."},{"id":"CL-16-A","subject":"Constitutional Law","topic":"Free Exercise neutral law","type":"application","question":"A neutral, generally applicable safety law incidentally burdens a person's religious practice. What principle generally applies?","options":["Free Exercise neutral law","Spending Clause conditions","Procedural due process","Content-based speech restriction"],"answer":0,"explanation":"Free Exercise neutral law: Neutral, generally applicable laws usually do not violate Free Exercise merely because they incidentally burden religion."},{"id":"CL-16-B","subject":"Constitutional Law","topic":"Free Exercise neutral law","type":"rule","question":"Which statement correctly describes Free Exercise neutral law?","options":["Content-based speech regulations generally receive strict scrutiny unless an established exception applies.","Government deprivation of protected life, liberty, or property interests ordinarily requires constitutionally appropriate process.","Neutral, generally applicable laws usually do not violate Free Exercise merely because they incidentally burden religion.","Congress may attach clear, related, noncoercive conditions to federal spending, within constitutional limits."],"answer":2,"explanation":"Free Exercise neutral law: Neutral, generally applicable laws usually do not violate Free Exercise merely because they incidentally burden religion."},{"id":"CL-17-A","subject":"Constitutional Law","topic":"Takings Clause","type":"application","question":"Government takes a parcel for a public road with payment of fair compensation. What clause applies?","options":["Takings Clause","State action doctrine","Time-place-manner regulation","Anti-commandeering principle"],"answer":0,"explanation":"Takings Clause: The Fifth Amendment Takings Clause requires public use and just compensation for covered government takings."},{"id":"CL-17-B","subject":"Constitutional Law","topic":"Takings Clause","type":"rule","question":"Which statement correctly describes Takings Clause?","options":["The Fifth Amendment Takings Clause requires public use and just compensation for covered government takings.","Content-neutral time, place, and manner limits must be appropriately tailored and leave adequate alternatives.","Many constitutional rights constrain government conduct rather than purely private action.","Congress ordinarily may not directly command state governments to legislate or administer federal programs."],"answer":0,"explanation":"Takings Clause: The Fifth Amendment Takings Clause requires public use and just compensation for covered government takings."},{"id":"CL-18-A","subject":"Constitutional Law","topic":"Supremacy Clause preemption","type":"application","question":"A valid federal statute directly conflicts with a state law. What principle resolves the conflict?","options":["True threats","Commerce Clause aggregation","Supremacy Clause preemption","Strict scrutiny for race"],"answer":2,"explanation":"Supremacy Clause preemption: Valid federal law displaces conflicting state law under the Supremacy Clause."},{"id":"CL-18-B","subject":"Constitutional Law","topic":"Supremacy Clause preemption","type":"rule","question":"Which statement correctly describes Supremacy Clause preemption?","options":["True threats constitute a limited category of speech that may be punished within constitutional requirements.","Valid federal law displaces conflicting state law under the Supremacy Clause.","Government racial classifications face strict scrutiny requiring a compelling interest and narrow tailoring.","Congress may regulate local economic activity whose aggregate effect substantially affects interstate commerce."],"answer":1,"explanation":"Supremacy Clause preemption: Valid federal law displaces conflicting state law under the Supremacy Clause."},{"id":"CL-19-A","subject":"Constitutional Law","topic":"Article III standing","type":"application","question":"A person sues over a policy but alleges no concrete personal harm. Which requirement is missing?","options":["Ex post facto prohibition","Anti-commandeering principle","Incitement standard","Article III standing"],"answer":3,"explanation":"Article III standing: Federal standing generally requires injury in fact, causation, and likely redressability."},{"id":"CL-19-B","subject":"Constitutional Law","topic":"Article III standing","type":"rule","question":"Which statement correctly describes Article III standing?","options":["Unprotected incitement requires advocacy intended and likely to produce imminent lawless action.","The Ex Post Facto Clauses prohibit certain retroactive criminal laws, including criminalizing previously lawful conduct.","Congress ordinarily may not directly command state governments to legislate or administer federal programs.","Federal standing generally requires injury in fact, causation, and likely redressability."],"answer":3,"explanation":"Article III standing: Federal standing generally requires injury in fact, causation, and likely redressability."},{"id":"CL-20-A","subject":"Constitutional Law","topic":"Ex post facto prohibition","type":"application","question":"A state criminalizes conduct that was lawful when committed and prosecutes it retroactively. Which constitutional bar applies?","options":["Rational-basis review","Ex post facto prohibition","Time-place-manner regulation","Supremacy Clause preemption"],"answer":1,"explanation":"Ex post facto prohibition: The Ex Post Facto Clauses prohibit certain retroactive criminal laws, including criminalizing previously lawful conduct."},{"id":"CL-20-B","subject":"Constitutional Law","topic":"Ex post facto prohibition","type":"rule","question":"Which statement correctly describes Ex post facto prohibition?","options":["The Ex Post Facto Clauses prohibit certain retroactive criminal laws, including criminalizing previously lawful conduct.","Content-neutral time, place, and manner limits must be appropriately tailored and leave adequate alternatives.","Valid federal law displaces conflicting state law under the Supremacy Clause.","Ordinary economic regulation generally needs a rational relation to a legitimate government purpose."],"answer":0,"explanation":"Ex post facto prohibition: The Ex Post Facto Clauses prohibit certain retroactive criminal laws, including criminalizing previously lawful conduct."},{"id":"C-01-A","subject":"Contracts","topic":"Offer","type":"application","question":"A seller says 'I will sell this bike for $400 if you accept Friday,' intending acceptance to bind both sides. What is this?","options":["Minor's contractual capacity","Offer","Consequential-damages foreseeability","Substantial performance"],"answer":1,"explanation":"Offer: An offer manifests willingness to bargain so the offeree's assent concludes the agreement."},{"id":"C-01-B","subject":"Contracts","topic":"Offer","type":"rule","question":"Which statement correctly describes Offer?","options":["Unusual consequential contract losses generally must have been foreseeable when the contract was formed.","An offer manifests willingness to bargain so the offeree's assent concludes the agreement.","Substantial performance may allow contract recovery despite a minor breach, subject to an offset for defects.","A minor's contract for non-necessaries is generally voidable at the minor's option, subject to exceptions."],"answer":1,"explanation":"Offer: An offer manifests willingness to bargain so the offeree's assent concludes the agreement."},{"id":"C-02-A","subject":"Contracts","topic":"Counteroffer","type":"application","question":"A buyer replies to a common-law land-sale offer, 'I agree if you also include the furniture.' What is the reply?","options":["Minor's contractual capacity","Substantial performance","Counteroffer","Statute of frauds for land"],"answer":2,"explanation":"Counteroffer: Under the common-law mirror-image rule, a material change normally makes the response a counteroffer."},{"id":"C-02-B","subject":"Contracts","topic":"Counteroffer","type":"rule","question":"Which statement correctly describes Counteroffer?","options":["A minor's contract for non-necessaries is generally voidable at the minor's option, subject to exceptions.","Contracts to convey interests in land ordinarily require a sufficient signed writing or a recognized exception.","Substantial performance may allow contract recovery despite a minor breach, subject to an offset for defects.","Under the common-law mirror-image rule, a material change normally makes the response a counteroffer."],"answer":3,"explanation":"Counteroffer: Under the common-law mirror-image rule, a material change normally makes the response a counteroffer."},{"id":"C-03-A","subject":"Contracts","topic":"UCC battle of the forms","type":"application","question":"Merchants exchange goods-contract forms, and the acceptance includes an additional term without expressly conditioning assent. Which rule governs?","options":["Minor's contractual capacity","Specific performance of land","Offer","UCC battle of the forms"],"answer":3,"explanation":"UCC battle of the forms: UCC 2-207 permits a definite acceptance despite additional or different terms, with special rules for their inclusion."},{"id":"C-03-B","subject":"Contracts","topic":"UCC battle of the forms","type":"rule","question":"Which statement correctly describes UCC battle of the forms?","options":["A minor's contract for non-necessaries is generally voidable at the minor's option, subject to exceptions.","Specific performance may be available where monetary damages are inadequate, especially for land.","UCC 2-207 permits a definite acceptance despite additional or different terms, with special rules for their inclusion.","An offer manifests willingness to bargain so the offeree's assent concludes the agreement."],"answer":2,"explanation":"UCC battle of the forms: UCC 2-207 permits a definite acceptance despite additional or different terms, with special rules for their inclusion."},{"id":"C-04-A","subject":"Contracts","topic":"Consideration","type":"application","question":"A painter agrees to paint a house and the owner agrees to pay an agreed sum. What makes the promises enforceable?","options":["Consequential-damages foreseeability","Right to cure","Consideration","UCC statute of frauds"],"answer":2,"explanation":"Consideration: Consideration is a bargained-for exchange of legal value or promises."},{"id":"C-04-B","subject":"Contracts","topic":"Consideration","type":"rule","question":"Which statement correctly describes Consideration?","options":["UCC 2-201 generally requires a sufficient signed writing for sales of goods priced at $500 or more.","A seller generally may cure a defective tender within the agreed time for performance.","Unusual consequential contract losses generally must have been foreseeable when the contract was formed.","Consideration is a bargained-for exchange of legal value or promises."],"answer":3,"explanation":"Consideration: Consideration is a bargained-for exchange of legal value or promises."},{"id":"C-05-A","subject":"Contracts","topic":"Past consideration","type":"application","question":"A neighbor promises cash as thanks for a favor already completed with no prior arrangement. What obstacle exists?","options":["Substantial performance","Promissory estoppel","Duress","Past consideration"],"answer":3,"explanation":"Past consideration: Past services generally are not consideration for a subsequent promise."},{"id":"C-05-B","subject":"Contracts","topic":"Past consideration","type":"rule","question":"Which statement correctly describes Past consideration?","options":["Improper threats that leave no reasonable alternative may make an agreement voidable for duress.","Substantial performance may allow contract recovery despite a minor breach, subject to an offset for defects.","Reasonable, foreseeable reliance on a promise may support relief when needed to avoid injustice.","Past services generally are not consideration for a subsequent promise."],"answer":3,"explanation":"Past consideration: Past services generally are not consideration for a subsequent promise."},{"id":"C-06-A","subject":"Contracts","topic":"Promissory estoppel","type":"application","question":"An employer makes a clear job promise, inducing a candidate to move at substantial expense before withdrawing it. What remedy theory fits?","options":["Promissory estoppel","UCC battle of the forms","Condition precedent","Expectation damages"],"answer":0,"explanation":"Promissory estoppel: Reasonable, foreseeable reliance on a promise may support relief when needed to avoid injustice."},{"id":"C-06-B","subject":"Contracts","topic":"Promissory estoppel","type":"rule","question":"Which statement correctly describes Promissory estoppel?","options":["A condition precedent is an event that must occur before an affected performance duty becomes due.","Reasonable, foreseeable reliance on a promise may support relief when needed to avoid injustice.","Expectation damages aim to put the injured party in the position performance would have produced.","UCC 2-207 permits a definite acceptance despite additional or different terms, with special rules for their inclusion."],"answer":1,"explanation":"Promissory estoppel: Reasonable, foreseeable reliance on a promise may support relief when needed to avoid injustice."},{"id":"C-07-A","subject":"Contracts","topic":"Minor's contractual capacity","type":"application","question":"A 16-year-old timely disaffirms a non-necessaries purchase contract. Which defense applies?","options":["Consideration","Duress","Perfect tender","Minor's contractual capacity"],"answer":3,"explanation":"Minor's contractual capacity: A minor's contract for non-necessaries is generally voidable at the minor's option, subject to exceptions."},{"id":"C-07-B","subject":"Contracts","topic":"Minor's contractual capacity","type":"rule","question":"Which statement correctly describes Minor's contractual capacity?","options":["For many single-delivery sales, the buyer may reject a nonconforming tender, subject to cure and exceptions.","A minor's contract for non-necessaries is generally voidable at the minor's option, subject to exceptions.","Consideration is a bargained-for exchange of legal value or promises.","Improper threats that leave no reasonable alternative may make an agreement voidable for duress."],"answer":1,"explanation":"Minor's contractual capacity: A minor's contract for non-necessaries is generally voidable at the minor's option, subject to exceptions."},{"id":"C-08-A","subject":"Contracts","topic":"Duress","type":"application","question":"Someone signs a deal only because the other side credibly threatens unlawful violence. Which defense applies?","options":["Condition precedent","Past consideration","Mutual mistake","Duress"],"answer":3,"explanation":"Duress: Improper threats that leave no reasonable alternative may make an agreement voidable for duress."},{"id":"C-08-B","subject":"Contracts","topic":"Duress","type":"rule","question":"Which statement correctly describes Duress?","options":["A condition precedent is an event that must occur before an affected performance duty becomes due.","Past services generally are not consideration for a subsequent promise.","Improper threats that leave no reasonable alternative may make an agreement voidable for duress.","Material mutual mistake about a basic assumption may permit avoidance if the complaining party did not bear the risk."],"answer":2,"explanation":"Duress: Improper threats that leave no reasonable alternative may make an agreement voidable for duress."},{"id":"C-09-A","subject":"Contracts","topic":"Mutual mistake","type":"application","question":"Both parties wrongly believe a painting is an original, a basic assumption critical to the sale. Which doctrine applies?","options":["Mutual mistake","Promissory estoppel","Condition precedent","Duress"],"answer":0,"explanation":"Mutual mistake: Material mutual mistake about a basic assumption may permit avoidance if the complaining party did not bear the risk."},{"id":"C-09-B","subject":"Contracts","topic":"Mutual mistake","type":"rule","question":"Which statement correctly describes Mutual mistake?","options":["A condition precedent is an event that must occur before an affected performance duty becomes due.","Improper threats that leave no reasonable alternative may make an agreement voidable for duress.","Material mutual mistake about a basic assumption may permit avoidance if the complaining party did not bear the risk.","Reasonable, foreseeable reliance on a promise may support relief when needed to avoid injustice."],"answer":2,"explanation":"Mutual mistake: Material mutual mistake about a basic assumption may permit avoidance if the complaining party did not bear the risk."},{"id":"C-10-A","subject":"Contracts","topic":"Statute of frauds for land","type":"application","question":"Parties orally agree to transfer a parcel of land next month. Which formal requirement applies?","options":["Statute of frauds for land","Condition precedent","Counteroffer","Mutual mistake"],"answer":0,"explanation":"Statute of frauds for land: Contracts to convey interests in land ordinarily require a sufficient signed writing or a recognized exception."},{"id":"C-10-B","subject":"Contracts","topic":"Statute of frauds for land","type":"rule","question":"Which statement correctly describes Statute of frauds for land?","options":["Contracts to convey interests in land ordinarily require a sufficient signed writing or a recognized exception.","A condition precedent is an event that must occur before an affected performance duty becomes due.","Material mutual mistake about a basic assumption may permit avoidance if the complaining party did not bear the risk.","Under the common-law mirror-image rule, a material change normally makes the response a counteroffer."],"answer":0,"explanation":"Statute of frauds for land: Contracts to convey interests in land ordinarily require a sufficient signed writing or a recognized exception."},{"id":"C-11-A","subject":"Contracts","topic":"UCC statute of frauds","type":"application","question":"Two parties orally contract for $2,500 of goods without satisfying an exception. Which rule is relevant?","options":["Right to cure","Statute of frauds for land","Specific performance of land","UCC statute of frauds"],"answer":3,"explanation":"UCC statute of frauds: UCC 2-201 generally requires a sufficient signed writing for sales of goods priced at $500 or more."},{"id":"C-11-B","subject":"Contracts","topic":"UCC statute of frauds","type":"rule","question":"Which statement correctly describes UCC statute of frauds?","options":["UCC 2-201 generally requires a sufficient signed writing for sales of goods priced at $500 or more.","Specific performance may be available where monetary damages are inadequate, especially for land.","A seller generally may cure a defective tender within the agreed time for performance.","Contracts to convey interests in land ordinarily require a sufficient signed writing or a recognized exception."],"answer":0,"explanation":"UCC statute of frauds: UCC 2-201 generally requires a sufficient signed writing for sales of goods priced at $500 or more."},{"id":"C-12-A","subject":"Contracts","topic":"Parol evidence rule","type":"application","question":"A complete final written contract is contradicted by evidence of a prior oral promise. What rule may exclude the oral term?","options":["Statute of frauds for land","Parol evidence rule","Expectation damages","Perfect tender"],"answer":1,"explanation":"Parol evidence rule: Prior or contemporaneous agreements ordinarily cannot contradict a complete integrated writing."},{"id":"C-12-B","subject":"Contracts","topic":"Parol evidence rule","type":"rule","question":"Which statement correctly describes Parol evidence rule?","options":["For many single-delivery sales, the buyer may reject a nonconforming tender, subject to cure and exceptions.","Expectation damages aim to put the injured party in the position performance would have produced.","Prior or contemporaneous agreements ordinarily cannot contradict a complete integrated writing.","Contracts to convey interests in land ordinarily require a sufficient signed writing or a recognized exception."],"answer":2,"explanation":"Parol evidence rule: Prior or contemporaneous agreements ordinarily cannot contradict a complete integrated writing."},{"id":"C-13-A","subject":"Contracts","topic":"Condition precedent","type":"application","question":"A land contract makes bank approval necessary before a buyer must close. What type of contract term is approval?","options":["Condition precedent","Perfect tender","Mutual mistake","Promissory estoppel"],"answer":0,"explanation":"Condition precedent: A condition precedent is an event that must occur before an affected performance duty becomes due."},{"id":"C-13-B","subject":"Contracts","topic":"Condition precedent","type":"rule","question":"Which statement correctly describes Condition precedent?","options":["For many single-delivery sales, the buyer may reject a nonconforming tender, subject to cure and exceptions.","Material mutual mistake about a basic assumption may permit avoidance if the complaining party did not bear the risk.","A condition precedent is an event that must occur before an affected performance duty becomes due.","Reasonable, foreseeable reliance on a promise may support relief when needed to avoid injustice."],"answer":2,"explanation":"Condition precedent: A condition precedent is an event that must occur before an affected performance duty becomes due."},{"id":"C-14-A","subject":"Contracts","topic":"Substantial performance","type":"application","question":"A builder completes a house with a minor nonmaterial defect and seeks payment less the cost to fix it. Which principle applies?","options":["Substantial performance","Specific performance of land","Consequential-damages foreseeability","UCC statute of frauds"],"answer":0,"explanation":"Substantial performance: Substantial performance may allow contract recovery despite a minor breach, subject to an offset for defects."},{"id":"C-14-B","subject":"Contracts","topic":"Substantial performance","type":"rule","question":"Which statement correctly describes Substantial performance?","options":["UCC 2-201 generally requires a sufficient signed writing for sales of goods priced at $500 or more.","Specific performance may be available where monetary damages are inadequate, especially for land.","Unusual consequential contract losses generally must have been foreseeable when the contract was formed.","Substantial performance may allow contract recovery despite a minor breach, subject to an offset for defects."],"answer":3,"explanation":"Substantial performance: Substantial performance may allow contract recovery despite a minor breach, subject to an offset for defects."},{"id":"C-15-A","subject":"Contracts","topic":"Anticipatory repudiation","type":"application","question":"A seller unequivocally announces before the delivery date that no goods will be shipped. What doctrine applies?","options":["Substantial performance","Perfect tender","Anticipatory repudiation","Offer"],"answer":2,"explanation":"Anticipatory repudiation: A clear advance refusal to perform can constitute anticipatory repudiation with resulting remedies."},{"id":"C-15-B","subject":"Contracts","topic":"Anticipatory repudiation","type":"rule","question":"Which statement correctly describes Anticipatory repudiation?","options":["A clear advance refusal to perform can constitute anticipatory repudiation with resulting remedies.","For many single-delivery sales, the buyer may reject a nonconforming tender, subject to cure and exceptions.","Substantial performance may allow contract recovery despite a minor breach, subject to an offset for defects.","An offer manifests willingness to bargain so the offeree's assent concludes the agreement."],"answer":0,"explanation":"Anticipatory repudiation: A clear advance refusal to perform can constitute anticipatory repudiation with resulting remedies."},{"id":"C-16-A","subject":"Contracts","topic":"Perfect tender","type":"application","question":"A one-time shipment of goods does not conform to the contract description. Which UCC buyer remedy principle applies?","options":["Offer","Counteroffer","Condition precedent","Perfect tender"],"answer":3,"explanation":"Perfect tender: For many single-delivery sales, the buyer may reject a nonconforming tender, subject to cure and exceptions."},{"id":"C-16-B","subject":"Contracts","topic":"Perfect tender","type":"rule","question":"Which statement correctly describes Perfect tender?","options":["For many single-delivery sales, the buyer may reject a nonconforming tender, subject to cure and exceptions.","Under the common-law mirror-image rule, a material change normally makes the response a counteroffer.","An offer manifests willingness to bargain so the offeree's assent concludes the agreement.","A condition precedent is an event that must occur before an affected performance duty becomes due."],"answer":0,"explanation":"Perfect tender: For many single-delivery sales, the buyer may reject a nonconforming tender, subject to cure and exceptions."},{"id":"C-17-A","subject":"Contracts","topic":"Right to cure","type":"application","question":"A seller ships a wrong item before the contract deadline and offers the correct item before that date. What UCC right applies?","options":["Consideration","Anticipatory repudiation","Right to cure","Past consideration"],"answer":2,"explanation":"Right to cure: A seller generally may cure a defective tender within the agreed time for performance."},{"id":"C-17-B","subject":"Contracts","topic":"Right to cure","type":"rule","question":"Which statement correctly describes Right to cure?","options":["A seller generally may cure a defective tender within the agreed time for performance.","Past services generally are not consideration for a subsequent promise.","A clear advance refusal to perform can constitute anticipatory repudiation with resulting remedies.","Consideration is a bargained-for exchange of legal value or promises."],"answer":0,"explanation":"Right to cure: A seller generally may cure a defective tender within the agreed time for performance."},{"id":"C-18-A","subject":"Contracts","topic":"Expectation damages","type":"application","question":"The injured buyer seeks the value of the promised performance rather than what was delivered. What measure applies?","options":["Parol evidence rule","UCC statute of frauds","Consideration","Expectation damages"],"answer":3,"explanation":"Expectation damages: Expectation damages aim to put the injured party in the position performance would have produced."},{"id":"C-18-B","subject":"Contracts","topic":"Expectation damages","type":"rule","question":"Which statement correctly describes Expectation damages?","options":["Expectation damages aim to put the injured party in the position performance would have produced.","Consideration is a bargained-for exchange of legal value or promises.","Prior or contemporaneous agreements ordinarily cannot contradict a complete integrated writing.","UCC 2-201 generally requires a sufficient signed writing for sales of goods priced at $500 or more."],"answer":0,"explanation":"Expectation damages: Expectation damages aim to put the injured party in the position performance would have produced."},{"id":"C-19-A","subject":"Contracts","topic":"Consequential-damages foreseeability","type":"application","question":"A carrier knows at contracting that late delivery will halt an unusual production line. Which damages limitation matters?","options":["Consequential-damages foreseeability","Anticipatory repudiation","Minor's contractual capacity","Promissory estoppel"],"answer":0,"explanation":"Consequential-damages foreseeability: Unusual consequential contract losses generally must have been foreseeable when the contract was formed."},{"id":"C-19-B","subject":"Contracts","topic":"Consequential-damages foreseeability","type":"rule","question":"Which statement correctly describes Consequential-damages foreseeability?","options":["A minor's contract for non-necessaries is generally voidable at the minor's option, subject to exceptions.","A clear advance refusal to perform can constitute anticipatory repudiation with resulting remedies.","Reasonable, foreseeable reliance on a promise may support relief when needed to avoid injustice.","Unusual consequential contract losses generally must have been foreseeable when the contract was formed."],"answer":3,"explanation":"Consequential-damages foreseeability: Unusual consequential contract losses generally must have been foreseeable when the contract was formed."},{"id":"C-20-A","subject":"Contracts","topic":"Specific performance of land","type":"application","question":"A seller breaches an agreement to convey a unique parcel. Which remedy may a court grant?","options":["UCC statute of frauds","Specific performance of land","Statute of frauds for land","Consequential-damages foreseeability"],"answer":1,"explanation":"Specific performance of land: Specific performance may be available where monetary damages are inadequate, especially for land."},{"id":"C-20-B","subject":"Contracts","topic":"Specific performance of land","type":"rule","question":"Which statement correctly describes Specific performance of land?","options":["Unusual consequential contract losses generally must have been foreseeable when the contract was formed.","UCC 2-201 generally requires a sufficient signed writing for sales of goods priced at $500 or more.","Specific performance may be available where monetary damages are inadequate, especially for land.","Contracts to convey interests in land ordinarily require a sufficient signed writing or a recognized exception."],"answer":2,"explanation":"Specific performance of land: Specific performance may be available where monetary damages are inadequate, especially for land."},{"id":"CLaP-01-A","subject":"Criminal Law and Procedure","topic":"Criminal attempt","type":"application","question":"A person intends a robbery and takes a substantial step but is stopped before taking property. What crime is established?","options":["Search-warrant probable cause","Criminal attempt","Robbery","Conspiracy"],"answer":1,"explanation":"Criminal attempt: Attempt generally requires intent to commit the target offense and a substantial step toward it."},{"id":"CLaP-01-B","subject":"Criminal Law and Procedure","topic":"Criminal attempt","type":"rule","question":"Which statement correctly describes Criminal attempt?","options":["A warrant ordinarily needs probable cause, a neutral magistrate, and particularity.","Robbery is generally larceny from another's person or presence by force or intimidation.","Attempt generally requires intent to commit the target offense and a substantial step toward it.","Conspiracy generally requires an agreement and intent to pursue unlawful conduct, sometimes with an overt act."],"answer":2,"explanation":"Criminal attempt: Attempt generally requires intent to commit the target offense and a substantial step toward it."},{"id":"CLaP-02-A","subject":"Criminal Law and Procedure","topic":"Solicitation","type":"application","question":"A person intentionally asks another to commit burglary, but the other refuses. What crime can already be complete?","options":["Solicitation","Terry stop","Miranda warnings","Involuntary manslaughter"],"answer":0,"explanation":"Solicitation: Solicitation generally is completed by intentionally requesting or encouraging another to commit crime."},{"id":"CLaP-02-B","subject":"Criminal Law and Procedure","topic":"Solicitation","type":"rule","question":"Which statement correctly describes Solicitation?","options":["A brief investigative stop may be supported by reasonable suspicion based on specific articulable facts.","Criminal recklessness or gross negligence causing death can support involuntary manslaughter under relevant law.","Solicitation generally is completed by intentionally requesting or encouraging another to commit crime.","Miranda warnings generally protect against use of unwarned custodial interrogation in the prosecution's case-in-chief."],"answer":2,"explanation":"Solicitation: Solicitation generally is completed by intentionally requesting or encouraging another to commit crime."},{"id":"CLaP-03-A","subject":"Criminal Law and Procedure","topic":"Conspiracy","type":"application","question":"Two people agree and intend to commit a felony, with an overt act where required. Which offense exists?","options":["Conspiracy","Sixth Amendment counsel","Felony murder","Necessity"],"answer":0,"explanation":"Conspiracy: Conspiracy generally requires an agreement and intent to pursue unlawful conduct, sometimes with an overt act."},{"id":"CLaP-03-B","subject":"Criminal Law and Procedure","topic":"Conspiracy","type":"rule","question":"Which statement correctly describes Conspiracy?","options":["The offense-specific Sixth Amendment counsel right attaches after formal adversary proceedings begin.","Felony murder may impose murder liability for qualifying killings tied to specified felonies, subject to limitations.","Conspiracy generally requires an agreement and intent to pursue unlawful conduct, sometimes with an overt act.","Necessity can justify a lesser harm to prevent a greater imminent harm where legal requirements are met."],"answer":2,"explanation":"Conspiracy: Conspiracy generally requires an agreement and intent to pursue unlawful conduct, sometimes with an overt act."},{"id":"CLaP-04-A","subject":"Criminal Law and Procedure","topic":"Accomplice liability","type":"application","question":"A lookout intentionally aids a planned robbery knowing and intending it to succeed. What theory applies?","options":["Sixth Amendment counsel","Felony murder","Accomplice liability","False pretenses"],"answer":2,"explanation":"Accomplice liability: An accomplice intentionally assists or encourages commission of a crime with the required culpability."},{"id":"CLaP-04-B","subject":"Criminal Law and Procedure","topic":"Accomplice liability","type":"rule","question":"Which statement correctly describes Accomplice liability?","options":["An accomplice intentionally assists or encourages commission of a crime with the required culpability.","The offense-specific Sixth Amendment counsel right attaches after formal adversary proceedings begin.","Felony murder may impose murder liability for qualifying killings tied to specified felonies, subject to limitations.","False pretenses involves obtaining title to another's property through intentional material misrepresentation."],"answer":0,"explanation":"Accomplice liability: An accomplice intentionally assists or encourages commission of a crime with the required culpability."},{"id":"CLaP-05-A","subject":"Criminal Law and Procedure","topic":"Felony murder","type":"application","question":"A participant causes a killing during and in furtherance of an enumerated dangerous felony. What homicide doctrine applies?","options":["Solicitation","Robbery","Felony murder","Miranda warnings"],"answer":2,"explanation":"Felony murder: Felony murder may impose murder liability for qualifying killings tied to specified felonies, subject to limitations."},{"id":"CLaP-05-B","subject":"Criminal Law and Procedure","topic":"Felony murder","type":"rule","question":"Which statement correctly describes Felony murder?","options":["Felony murder may impose murder liability for qualifying killings tied to specified felonies, subject to limitations.","Miranda warnings generally protect against use of unwarned custodial interrogation in the prosecution's case-in-chief.","Robbery is generally larceny from another's person or presence by force or intimidation.","Solicitation generally is completed by intentionally requesting or encouraging another to commit crime."],"answer":0,"explanation":"Felony murder: Felony murder may impose murder liability for qualifying killings tied to specified felonies, subject to limitations."},{"id":"CLaP-06-A","subject":"Criminal Law and Procedure","topic":"Voluntary manslaughter","type":"application","question":"An intentional killing follows legally adequate provocation in the heat of passion without cooling time. What mitigation may apply?","options":["Terry stop","Voluntary manslaughter","Necessity","Miranda warnings"],"answer":1,"explanation":"Voluntary manslaughter: Adequate provocation and heat of passion can mitigate an intentional killing from murder to voluntary manslaughter."},{"id":"CLaP-06-B","subject":"Criminal Law and Procedure","topic":"Voluntary manslaughter","type":"rule","question":"Which statement correctly describes Voluntary manslaughter?","options":["A brief investigative stop may be supported by reasonable suspicion based on specific articulable facts.","Necessity can justify a lesser harm to prevent a greater imminent harm where legal requirements are met.","Adequate provocation and heat of passion can mitigate an intentional killing from murder to voluntary manslaughter.","Miranda warnings generally protect against use of unwarned custodial interrogation in the prosecution's case-in-chief."],"answer":2,"explanation":"Voluntary manslaughter: Adequate provocation and heat of passion can mitigate an intentional killing from murder to voluntary manslaughter."},{"id":"CLaP-07-A","subject":"Criminal Law and Procedure","topic":"Involuntary manslaughter","type":"application","question":"A driver recklessly disregards a grave unjustifiable risk and unintentionally kills someone. What offense may apply?","options":["Involuntary manslaughter","Search-warrant probable cause","False pretenses","Sixth Amendment counsel"],"answer":0,"explanation":"Involuntary manslaughter: Criminal recklessness or gross negligence causing death can support involuntary manslaughter under relevant law."},{"id":"CLaP-07-B","subject":"Criminal Law and Procedure","topic":"Involuntary manslaughter","type":"rule","question":"Which statement correctly describes Involuntary manslaughter?","options":["A warrant ordinarily needs probable cause, a neutral magistrate, and particularity.","The offense-specific Sixth Amendment counsel right attaches after formal adversary proceedings begin.","Criminal recklessness or gross negligence causing death can support involuntary manslaughter under relevant law.","False pretenses involves obtaining title to another's property through intentional material misrepresentation."],"answer":2,"explanation":"Involuntary manslaughter: Criminal recklessness or gross negligence causing death can support involuntary manslaughter under relevant law."},{"id":"CLaP-08-A","subject":"Criminal Law and Procedure","topic":"Self-defense","type":"application","question":"A person reasonably believes deadly force is immediately needed to stop a deadly attack. Which justification applies?","options":["Felony murder","Criminal attempt","Self-defense","False pretenses"],"answer":2,"explanation":"Self-defense: Reasonably necessary force may be justified against an imminent unlawful threat, with limits on deadly force."},{"id":"CLaP-08-B","subject":"Criminal Law and Procedure","topic":"Self-defense","type":"rule","question":"Which statement correctly describes Self-defense?","options":["Reasonably necessary force may be justified against an imminent unlawful threat, with limits on deadly force.","Felony murder may impose murder liability for qualifying killings tied to specified felonies, subject to limitations.","Attempt generally requires intent to commit the target offense and a substantial step toward it.","False pretenses involves obtaining title to another's property through intentional material misrepresentation."],"answer":0,"explanation":"Self-defense: Reasonably necessary force may be justified against an imminent unlawful threat, with limits on deadly force."},{"id":"CLaP-09-A","subject":"Criminal Law and Procedure","topic":"Necessity","type":"application","question":"A stranded driver takes an unattended vehicle to escape an imminent natural disaster when no safe option exists. Which defense might apply?","options":["Common-law burglary","Necessity","Automobile exception","Involuntary manslaughter"],"answer":1,"explanation":"Necessity: Necessity can justify a lesser harm to prevent a greater imminent harm where legal requirements are met."},{"id":"CLaP-09-B","subject":"Criminal Law and Procedure","topic":"Necessity","type":"rule","question":"Which statement correctly describes Necessity?","options":["Probable cause permits a warrantless vehicle search within the scope of the objects sought, subject to law.","Common-law burglary requires breaking and entering another's dwelling at night with intent to commit a felony.","Necessity can justify a lesser harm to prevent a greater imminent harm where legal requirements are met.","Criminal recklessness or gross negligence causing death can support involuntary manslaughter under relevant law."],"answer":2,"explanation":"Necessity: Necessity can justify a lesser harm to prevent a greater imminent harm where legal requirements are met."},{"id":"CLaP-10-A","subject":"Criminal Law and Procedure","topic":"Larceny","type":"application","question":"A thief takes another's wallet without permission intending permanent deprivation. Which theft offense fits?","options":["Solicitation","Necessity","Automobile exception","Larceny"],"answer":3,"explanation":"Larceny: Larceny traditionally requires trespassory taking and carrying away another's personal property with intent to deprive permanently."},{"id":"CLaP-10-B","subject":"Criminal Law and Procedure","topic":"Larceny","type":"rule","question":"Which statement correctly describes Larceny?","options":["Solicitation generally is completed by intentionally requesting or encouraging another to commit crime.","Necessity can justify a lesser harm to prevent a greater imminent harm where legal requirements are met.","Probable cause permits a warrantless vehicle search within the scope of the objects sought, subject to law.","Larceny traditionally requires trespassory taking and carrying away another's personal property with intent to deprive permanently."],"answer":3,"explanation":"Larceny: Larceny traditionally requires trespassory taking and carrying away another's personal property with intent to deprive permanently."},{"id":"CLaP-11-A","subject":"Criminal Law and Procedure","topic":"Embezzlement","type":"application","question":"An employee lawfully holds company cash then fraudulently converts it to personal use. Which offense fits?","options":["False pretenses","Self-defense","Embezzlement","Criminal attempt"],"answer":2,"explanation":"Embezzlement: Embezzlement is fraudulent conversion of property by someone already in lawful possession."},{"id":"CLaP-11-B","subject":"Criminal Law and Procedure","topic":"Embezzlement","type":"rule","question":"Which statement correctly describes Embezzlement?","options":["False pretenses involves obtaining title to another's property through intentional material misrepresentation.","Embezzlement is fraudulent conversion of property by someone already in lawful possession.","Reasonably necessary force may be justified against an imminent unlawful threat, with limits on deadly force.","Attempt generally requires intent to commit the target offense and a substantial step toward it."],"answer":1,"explanation":"Embezzlement: Embezzlement is fraudulent conversion of property by someone already in lawful possession."},{"id":"CLaP-12-A","subject":"Criminal Law and Procedure","topic":"False pretenses","type":"application","question":"A fraudster lies to obtain legal title to a car from a deceived seller. What offense fits?","options":["Criminal attempt","False pretenses","Voluntary manslaughter","Common-law burglary"],"answer":1,"explanation":"False pretenses: False pretenses involves obtaining title to another's property through intentional material misrepresentation."},{"id":"CLaP-12-B","subject":"Criminal Law and Procedure","topic":"False pretenses","type":"rule","question":"Which statement correctly describes False pretenses?","options":["Common-law burglary requires breaking and entering another's dwelling at night with intent to commit a felony.","Attempt generally requires intent to commit the target offense and a substantial step toward it.","False pretenses involves obtaining title to another's property through intentional material misrepresentation.","Adequate provocation and heat of passion can mitigate an intentional killing from murder to voluntary manslaughter."],"answer":2,"explanation":"False pretenses: False pretenses involves obtaining title to another's property through intentional material misrepresentation."},{"id":"CLaP-13-A","subject":"Criminal Law and Procedure","topic":"Robbery","type":"application","question":"A thief uses immediate force to seize a purse from the victim's person. Which offense applies?","options":["Miranda warnings","Robbery","Self-defense","Automobile exception"],"answer":1,"explanation":"Robbery: Robbery is generally larceny from another's person or presence by force or intimidation."},{"id":"CLaP-13-B","subject":"Criminal Law and Procedure","topic":"Robbery","type":"rule","question":"Which statement correctly describes Robbery?","options":["Robbery is generally larceny from another's person or presence by force or intimidation.","Reasonably necessary force may be justified against an imminent unlawful threat, with limits on deadly force.","Miranda warnings generally protect against use of unwarned custodial interrogation in the prosecution's case-in-chief.","Probable cause permits a warrantless vehicle search within the scope of the objects sought, subject to law."],"answer":0,"explanation":"Robbery: Robbery is generally larceny from another's person or presence by force or intimidation."},{"id":"CLaP-14-A","subject":"Criminal Law and Procedure","topic":"Common-law burglary","type":"application","question":"A person breaks into another's dwelling at night intending to commit a felony inside. What offense fits?","options":["Robbery","Involuntary manslaughter","Common-law burglary","Automobile exception"],"answer":2,"explanation":"Common-law burglary: Common-law burglary requires breaking and entering another's dwelling at night with intent to commit a felony."},{"id":"CLaP-14-B","subject":"Criminal Law and Procedure","topic":"Common-law burglary","type":"rule","question":"Which statement correctly describes Common-law burglary?","options":["Criminal recklessness or gross negligence causing death can support involuntary manslaughter under relevant law.","Robbery is generally larceny from another's person or presence by force or intimidation.","Common-law burglary requires breaking and entering another's dwelling at night with intent to commit a felony.","Probable cause permits a warrantless vehicle search within the scope of the objects sought, subject to law."],"answer":2,"explanation":"Common-law burglary: Common-law burglary requires breaking and entering another's dwelling at night with intent to commit a felony."},{"id":"CLaP-15-A","subject":"Criminal Law and Procedure","topic":"Search-warrant probable cause","type":"application","question":"Officers show a fair probability that evidence will be found in a specified house. What level supports a search warrant?","options":["Self-defense","Search-warrant probable cause","Common-law burglary","Voluntary manslaughter"],"answer":1,"explanation":"Search-warrant probable cause: A warrant ordinarily needs probable cause, a neutral magistrate, and particularity."},{"id":"CLaP-15-B","subject":"Criminal Law and Procedure","topic":"Search-warrant probable cause","type":"rule","question":"Which statement correctly describes Search-warrant probable cause?","options":["Common-law burglary requires breaking and entering another's dwelling at night with intent to commit a felony.","A warrant ordinarily needs probable cause, a neutral magistrate, and particularity.","Adequate provocation and heat of passion can mitigate an intentional killing from murder to voluntary manslaughter.","Reasonably necessary force may be justified against an imminent unlawful threat, with limits on deadly force."],"answer":1,"explanation":"Search-warrant probable cause: A warrant ordinarily needs probable cause, a neutral magistrate, and particularity."},{"id":"CLaP-16-A","subject":"Criminal Law and Procedure","topic":"Terry stop","type":"application","question":"An officer briefly detains a pedestrian based on articulable facts suggesting crime is afoot. What standard permits the stop?","options":["Voluntary manslaughter","False pretenses","Terry stop","Criminal attempt"],"answer":2,"explanation":"Terry stop: A brief investigative stop may be supported by reasonable suspicion based on specific articulable facts."},{"id":"CLaP-16-B","subject":"Criminal Law and Procedure","topic":"Terry stop","type":"rule","question":"Which statement correctly describes Terry stop?","options":["A brief investigative stop may be supported by reasonable suspicion based on specific articulable facts.","False pretenses involves obtaining title to another's property through intentional material misrepresentation.","Attempt generally requires intent to commit the target offense and a substantial step toward it.","Adequate provocation and heat of passion can mitigate an intentional killing from murder to voluntary manslaughter."],"answer":0,"explanation":"Terry stop: A brief investigative stop may be supported by reasonable suspicion based on specific articulable facts."},{"id":"CLaP-17-A","subject":"Criminal Law and Procedure","topic":"Miranda warnings","type":"application","question":"Police question a suspect in custody in a way likely to elicit incriminating responses without warnings. Which doctrine applies?","options":["Miranda warnings","Felony murder","Embezzlement","Solicitation"],"answer":0,"explanation":"Miranda warnings: Miranda warnings generally protect against use of unwarned custodial interrogation in the prosecution's case-in-chief."},{"id":"CLaP-17-B","subject":"Criminal Law and Procedure","topic":"Miranda warnings","type":"rule","question":"Which statement correctly describes Miranda warnings?","options":["Felony murder may impose murder liability for qualifying killings tied to specified felonies, subject to limitations.","Miranda warnings generally protect against use of unwarned custodial interrogation in the prosecution's case-in-chief.","Solicitation generally is completed by intentionally requesting or encouraging another to commit crime.","Embezzlement is fraudulent conversion of property by someone already in lawful possession."],"answer":1,"explanation":"Miranda warnings: Miranda warnings generally protect against use of unwarned custodial interrogation in the prosecution's case-in-chief."},{"id":"CLaP-18-A","subject":"Criminal Law and Procedure","topic":"Sixth Amendment counsel","type":"application","question":"After formal charge, officers deliberately elicit statements about the charged crime without waiver or counsel. Which protection applies?","options":["Criminal attempt","Search-warrant probable cause","Conspiracy","Sixth Amendment counsel"],"answer":3,"explanation":"Sixth Amendment counsel: The offense-specific Sixth Amendment counsel right attaches after formal adversary proceedings begin."},{"id":"CLaP-18-B","subject":"Criminal Law and Procedure","topic":"Sixth Amendment counsel","type":"rule","question":"Which statement correctly describes Sixth Amendment counsel?","options":["Attempt generally requires intent to commit the target offense and a substantial step toward it.","A warrant ordinarily needs probable cause, a neutral magistrate, and particularity.","Conspiracy generally requires an agreement and intent to pursue unlawful conduct, sometimes with an overt act.","The offense-specific Sixth Amendment counsel right attaches after formal adversary proceedings begin."],"answer":3,"explanation":"Sixth Amendment counsel: The offense-specific Sixth Amendment counsel right attaches after formal adversary proceedings begin."},{"id":"CLaP-19-A","subject":"Criminal Law and Procedure","topic":"Automobile exception","type":"application","question":"Police have probable cause that a car contains stolen items and search compartments capable of hiding them. Which exception applies?","options":["Necessity","Criminal attempt","Automobile exception","Felony murder"],"answer":2,"explanation":"Automobile exception: Probable cause permits a warrantless vehicle search within the scope of the objects sought, subject to law."},{"id":"CLaP-19-B","subject":"Criminal Law and Procedure","topic":"Automobile exception","type":"rule","question":"Which statement correctly describes Automobile exception?","options":["Probable cause permits a warrantless vehicle search within the scope of the objects sought, subject to law.","Felony murder may impose murder liability for qualifying killings tied to specified felonies, subject to limitations.","Attempt generally requires intent to commit the target offense and a substantial step toward it.","Necessity can justify a lesser harm to prevent a greater imminent harm where legal requirements are met."],"answer":0,"explanation":"Automobile exception: Probable cause permits a warrantless vehicle search within the scope of the objects sought, subject to law."},{"id":"CLaP-20-A","subject":"Criminal Law and Procedure","topic":"Double-jeopardy attachment","type":"application","question":"A jury in a criminal trial is empaneled and sworn. What rule becomes relevant?","options":["Double-jeopardy attachment","Common-law burglary","Voluntary manslaughter","Accomplice liability"],"answer":0,"explanation":"Double-jeopardy attachment: Jeopardy normally attaches when the jury is sworn in a jury trial."},{"id":"CLaP-20-B","subject":"Criminal Law and Procedure","topic":"Double-jeopardy attachment","type":"rule","question":"Which statement correctly describes Double-jeopardy attachment?","options":["Adequate provocation and heat of passion can mitigate an intentional killing from murder to voluntary manslaughter.","Jeopardy normally attaches when the jury is sworn in a jury trial.","Common-law burglary requires breaking and entering another's dwelling at night with intent to commit a felony.","An accomplice intentionally assists or encourages commission of a crime with the required culpability."],"answer":1,"explanation":"Double-jeopardy attachment: Jeopardy normally attaches when the jury is sworn in a jury trial."},{"id":"E-01-A","subject":"Evidence","topic":"Relevance under Rule 401","type":"application","question":"A photo makes an important disputed fact slightly more probable. Which threshold rule applies?","options":["Present-sense impression","Prior inconsistent sworn statement","Bias impeachment","Relevance under Rule 401"],"answer":3,"explanation":"Relevance under Rule 401: Evidence is relevant if it has any tendency to make a consequential fact more or less probable."},{"id":"E-01-B","subject":"Evidence","topic":"Relevance under Rule 401","type":"rule","question":"Which statement correctly describes Relevance under Rule 401?","options":["Evidence is relevant if it has any tendency to make a consequential fact more or less probable.","Evidence of bias, interest, or motive is generally admissible to attack credibility.","A prior inconsistent statement given under oath at a trial, hearing, or deposition can be substantive nonhearsay.","A present-sense impression describes or explains an event while or immediately after the declarant perceives it."],"answer":0,"explanation":"Relevance under Rule 401: Evidence is relevant if it has any tendency to make a consequential fact more or less probable."},{"id":"E-02-A","subject":"Evidence","topic":"Rule 403 balancing","type":"application","question":"A gruesome exhibit has minor probative value greatly outweighed by unfair prejudice. What rule may exclude it?","options":["Rule 403 balancing","Statements for medical treatment","Recorded recollection","Excited utterance"],"answer":0,"explanation":"Rule 403 balancing: A judge may exclude relevant evidence if specified dangers substantially outweigh its probative value."},{"id":"E-02-B","subject":"Evidence","topic":"Rule 403 balancing","type":"rule","question":"Which statement correctly describes Rule 403 balancing?","options":["Rule 803(5) allows qualifying recorded recollection to be read into evidence when its foundation is met.","A judge may exclude relevant evidence if specified dangers substantially outweigh its probative value.","Statements reasonably pertinent to medical diagnosis or treatment may qualify under Rule 803(4).","An excited utterance relates to a startling event while the speaker remains under its stress."],"answer":1,"explanation":"Rule 403 balancing: A judge may exclude relevant evidence if specified dangers substantially outweigh its probative value."},{"id":"E-03-A","subject":"Evidence","topic":"Character propensity prohibition","type":"application","question":"A prosecutor offers the accused's bad temper solely to prove similar conduct on the charged occasion. What restriction applies?","options":["Hearsay definition","Confrontation Clause","Excited utterance","Character propensity prohibition"],"answer":3,"explanation":"Character propensity prohibition: Character evidence generally cannot prove conduct in conformity with a trait on a particular occasion, subject to exceptions."},{"id":"E-03-B","subject":"Evidence","topic":"Character propensity prohibition","type":"rule","question":"Which statement correctly describes Character propensity prohibition?","options":["An excited utterance relates to a startling event while the speaker remains under its stress.","Testimonial hearsay normally cannot be admitted against a criminal defendant without unavailability and a prior opportunity for cross-examination.","Hearsay is generally an out-of-court statement offered to prove the truth of its assertion.","Character evidence generally cannot prove conduct in conformity with a trait on a particular occasion, subject to exceptions."],"answer":3,"explanation":"Character propensity prohibition: Character evidence generally cannot prove conduct in conformity with a trait on a particular occasion, subject to exceptions."},{"id":"E-04-A","subject":"Evidence","topic":"Rule 404(b) other acts","type":"application","question":"An earlier act is genuinely offered to establish identity or motive rather than propensity. What rule governs?","options":["Business records","Rule 404(b) other acts","Opposing-party statement","Dying declaration"],"answer":1,"explanation":"Rule 404(b) other acts: Other acts may be admissible for a legitimate nonpropensity use, subject to other limits."},{"id":"E-04-B","subject":"Evidence","topic":"Rule 404(b) other acts","type":"rule","question":"Which statement correctly describes Rule 404(b) other acts?","options":["Other acts may be admissible for a legitimate nonpropensity use, subject to other limits.","Qualifying statements of an opposing party are treated as not hearsay under Rule 801(d)(2).","Qualifying records of regularly conducted activity may be admitted under Rule 803(6) with proper foundation.","A dying declaration about the cause or circumstances of impending death may be admitted in certain cases."],"answer":0,"explanation":"Rule 404(b) other acts: Other acts may be admissible for a legitimate nonpropensity use, subject to other limits."},{"id":"E-05-A","subject":"Evidence","topic":"Habit evidence","type":"application","question":"A person follows the same automatic safety-check routine each morning. What proof may show that routine occurred this morning?","options":["Attorney-client privilege","Recorded recollection","Prior inconsistent sworn statement","Habit evidence"],"answer":3,"explanation":"Habit evidence: A person's regular response to a specific repeated situation can be admissible as habit evidence."},{"id":"E-05-B","subject":"Evidence","topic":"Habit evidence","type":"rule","question":"Which statement correctly describes Habit evidence?","options":["Rule 803(5) allows qualifying recorded recollection to be read into evidence when its foundation is met.","A prior inconsistent statement given under oath at a trial, hearing, or deposition can be substantive nonhearsay.","Confidential communications made to obtain or provide legal advice generally may be privileged.","A person's regular response to a specific repeated situation can be admissible as habit evidence."],"answer":3,"explanation":"Habit evidence: A person's regular response to a specific repeated situation can be admissible as habit evidence."},{"id":"E-06-A","subject":"Evidence","topic":"Bias impeachment","type":"application","question":"A witness owns a financial interest in the company whose conduct is on trial. What impeachment method fits?","options":["Bias impeachment","Business records","Recorded recollection","Hearsay definition"],"answer":0,"explanation":"Bias impeachment: Evidence of bias, interest, or motive is generally admissible to attack credibility."},{"id":"E-06-B","subject":"Evidence","topic":"Bias impeachment","type":"rule","question":"Which statement correctly describes Bias impeachment?","options":["Qualifying records of regularly conducted activity may be admitted under Rule 803(6) with proper foundation.","Evidence of bias, interest, or motive is generally admissible to attack credibility.","Hearsay is generally an out-of-court statement offered to prove the truth of its assertion.","Rule 803(5) allows qualifying recorded recollection to be read into evidence when its foundation is met."],"answer":1,"explanation":"Bias impeachment: Evidence of bias, interest, or motive is generally admissible to attack credibility."},{"id":"E-07-A","subject":"Evidence","topic":"Hearsay definition","type":"application","question":"A witness quotes an out-of-court statement to prove that what the statement said was true. What rule is triggered?","options":["Habit evidence","Hearsay definition","Prior inconsistent sworn statement","Confrontation Clause"],"answer":1,"explanation":"Hearsay definition: Hearsay is generally an out-of-court statement offered to prove the truth of its assertion."},{"id":"E-07-B","subject":"Evidence","topic":"Hearsay definition","type":"rule","question":"Which statement correctly describes Hearsay definition?","options":["A person's regular response to a specific repeated situation can be admissible as habit evidence.","A prior inconsistent statement given under oath at a trial, hearing, or deposition can be substantive nonhearsay.","Hearsay is generally an out-of-court statement offered to prove the truth of its assertion.","Testimonial hearsay normally cannot be admitted against a criminal defendant without unavailability and a prior opportunity for cross-examination."],"answer":2,"explanation":"Hearsay definition: Hearsay is generally an out-of-court statement offered to prove the truth of its assertion."},{"id":"E-08-A","subject":"Evidence","topic":"Opposing-party statement","type":"application","question":"A plaintiff offers the defendant's own statement against that defendant. How is it treated?","options":["Opposing-party statement","Refreshing recollection","Recorded recollection","Statements for medical treatment"],"answer":0,"explanation":"Opposing-party statement: Qualifying statements of an opposing party are treated as not hearsay under Rule 801(d)(2)."},{"id":"E-08-B","subject":"Evidence","topic":"Opposing-party statement","type":"rule","question":"Which statement correctly describes Opposing-party statement?","options":["Statements reasonably pertinent to medical diagnosis or treatment may qualify under Rule 803(4).","Rule 803(5) allows qualifying recorded recollection to be read into evidence when its foundation is met.","Rule 612 permits writings to refresh a witness's present memory, with safeguards for the other party.","Qualifying statements of an opposing party are treated as not hearsay under Rule 801(d)(2)."],"answer":3,"explanation":"Opposing-party statement: Qualifying statements of an opposing party are treated as not hearsay under Rule 801(d)(2)."},{"id":"E-09-A","subject":"Evidence","topic":"Present-sense impression","type":"application","question":"A bystander says 'The car is turning left' while watching it happen. Which exception fits?","options":["Confrontation Clause","Relevance under Rule 401","Opposing-party statement","Present-sense impression"],"answer":3,"explanation":"Present-sense impression: A present-sense impression describes or explains an event while or immediately after the declarant perceives it."},{"id":"E-09-B","subject":"Evidence","topic":"Present-sense impression","type":"rule","question":"Which statement correctly describes Present-sense impression?","options":["Evidence is relevant if it has any tendency to make a consequential fact more or less probable.","Qualifying statements of an opposing party are treated as not hearsay under Rule 801(d)(2).","Testimonial hearsay normally cannot be admitted against a criminal defendant without unavailability and a prior opportunity for cross-examination.","A present-sense impression describes or explains an event while or immediately after the declarant perceives it."],"answer":3,"explanation":"Present-sense impression: A present-sense impression describes or explains an event while or immediately after the declarant perceives it."},{"id":"E-10-A","subject":"Evidence","topic":"Excited utterance","type":"application","question":"A shaken passenger immediately blurts out the cause of a frightening collision. What exception fits?","options":["Prior inconsistent sworn statement","Relevance under Rule 401","Excited utterance","Bias impeachment"],"answer":2,"explanation":"Excited utterance: An excited utterance relates to a startling event while the speaker remains under its stress."},{"id":"E-10-B","subject":"Evidence","topic":"Excited utterance","type":"rule","question":"Which statement correctly describes Excited utterance?","options":["A prior inconsistent statement given under oath at a trial, hearing, or deposition can be substantive nonhearsay.","An excited utterance relates to a startling event while the speaker remains under its stress.","Evidence is relevant if it has any tendency to make a consequential fact more or less probable.","Evidence of bias, interest, or motive is generally admissible to attack credibility."],"answer":1,"explanation":"Excited utterance: An excited utterance relates to a startling event while the speaker remains under its stress."},{"id":"E-11-A","subject":"Evidence","topic":"Dying declaration","type":"application","question":"A dying victim believing death imminent identifies the attacker in a homicide case. What exception may apply?","options":["Dying declaration","Lay opinion testimony","Character propensity prohibition","Present-sense impression"],"answer":0,"explanation":"Dying declaration: A dying declaration about the cause or circumstances of impending death may be admitted in certain cases."},{"id":"E-11-B","subject":"Evidence","topic":"Dying declaration","type":"rule","question":"Which statement correctly describes Dying declaration?","options":["A dying declaration about the cause or circumstances of impending death may be admitted in certain cases.","A present-sense impression describes or explains an event while or immediately after the declarant perceives it.","Lay opinion may be based on personal perception if helpful and not based on specialized expertise.","Character evidence generally cannot prove conduct in conformity with a trait on a particular occasion, subject to exceptions."],"answer":0,"explanation":"Dying declaration: A dying declaration about the cause or circumstances of impending death may be admitted in certain cases."},{"id":"E-12-A","subject":"Evidence","topic":"Business records","type":"application","question":"A store routinely maintains timely sales ledgers through employees with knowledge. Which exception fits?","options":["Attorney-client privilege","Excited utterance","Dying declaration","Business records"],"answer":3,"explanation":"Business records: Qualifying records of regularly conducted activity may be admitted under Rule 803(6) with proper foundation."},{"id":"E-12-B","subject":"Evidence","topic":"Business records","type":"rule","question":"Which statement correctly describes Business records?","options":["Confidential communications made to obtain or provide legal advice generally may be privileged.","An excited utterance relates to a startling event while the speaker remains under its stress.","A dying declaration about the cause or circumstances of impending death may be admitted in certain cases.","Qualifying records of regularly conducted activity may be admitted under Rule 803(6) with proper foundation."],"answer":3,"explanation":"Business records: Qualifying records of regularly conducted activity may be admitted under Rule 803(6) with proper foundation."},{"id":"E-13-A","subject":"Evidence","topic":"Statements for medical treatment","type":"application","question":"A patient tells a physician when symptoms began to aid diagnosis. Which exception fits?","options":["Refreshing recollection","Bias impeachment","Opposing-party statement","Statements for medical treatment"],"answer":3,"explanation":"Statements for medical treatment: Statements reasonably pertinent to medical diagnosis or treatment may qualify under Rule 803(4)."},{"id":"E-13-B","subject":"Evidence","topic":"Statements for medical treatment","type":"rule","question":"Which statement correctly describes Statements for medical treatment?","options":["Rule 612 permits writings to refresh a witness's present memory, with safeguards for the other party.","Statements reasonably pertinent to medical diagnosis or treatment may qualify under Rule 803(4).","Evidence of bias, interest, or motive is generally admissible to attack credibility.","Qualifying statements of an opposing party are treated as not hearsay under Rule 801(d)(2)."],"answer":1,"explanation":"Statements for medical treatment: Statements reasonably pertinent to medical diagnosis or treatment may qualify under Rule 803(4)."},{"id":"E-14-A","subject":"Evidence","topic":"Prior inconsistent sworn statement","type":"application","question":"A trial witness contradicts an earlier deposition statement given under oath. Which evidentiary rule may allow substantive use?","options":["Rule 404(b) other acts","Prior inconsistent sworn statement","Excited utterance","Habit evidence"],"answer":1,"explanation":"Prior inconsistent sworn statement: A prior inconsistent statement given under oath at a trial, hearing, or deposition can be substantive nonhearsay."},{"id":"E-14-B","subject":"Evidence","topic":"Prior inconsistent sworn statement","type":"rule","question":"Which statement correctly describes Prior inconsistent sworn statement?","options":["A person's regular response to a specific repeated situation can be admissible as habit evidence.","An excited utterance relates to a startling event while the speaker remains under its stress.","A prior inconsistent statement given under oath at a trial, hearing, or deposition can be substantive nonhearsay.","Other acts may be admissible for a legitimate nonpropensity use, subject to other limits."],"answer":2,"explanation":"Prior inconsistent sworn statement: A prior inconsistent statement given under oath at a trial, hearing, or deposition can be substantive nonhearsay."},{"id":"E-15-A","subject":"Evidence","topic":"Recorded recollection","type":"application","question":"A witness once knew a detail, cannot now remember it, and adopted an accurate note while memory was fresh. What exception fits?","options":["Relevance under Rule 401","Attorney-client privilege","Recorded recollection","Bias impeachment"],"answer":2,"explanation":"Recorded recollection: Rule 803(5) allows qualifying recorded recollection to be read into evidence when its foundation is met."},{"id":"E-15-B","subject":"Evidence","topic":"Recorded recollection","type":"rule","question":"Which statement correctly describes Recorded recollection?","options":["Confidential communications made to obtain or provide legal advice generally may be privileged.","Evidence of bias, interest, or motive is generally admissible to attack credibility.","Evidence is relevant if it has any tendency to make a consequential fact more or less probable.","Rule 803(5) allows qualifying recorded recollection to be read into evidence when its foundation is met."],"answer":3,"explanation":"Recorded recollection: Rule 803(5) allows qualifying recorded recollection to be read into evidence when its foundation is met."},{"id":"E-16-A","subject":"Evidence","topic":"Refreshing recollection","type":"application","question":"A witness consults a calendar to jog memory, then testifies from renewed personal knowledge. What method is used?","options":["Habit evidence","Rule 404(b) other acts","Refreshing recollection","Statements for medical treatment"],"answer":2,"explanation":"Refreshing recollection: Rule 612 permits writings to refresh a witness's present memory, with safeguards for the other party."},{"id":"E-16-B","subject":"Evidence","topic":"Refreshing recollection","type":"rule","question":"Which statement correctly describes Refreshing recollection?","options":["Statements reasonably pertinent to medical diagnosis or treatment may qualify under Rule 803(4).","Rule 612 permits writings to refresh a witness's present memory, with safeguards for the other party.","A person's regular response to a specific repeated situation can be admissible as habit evidence.","Other acts may be admissible for a legitimate nonpropensity use, subject to other limits."],"answer":1,"explanation":"Refreshing recollection: Rule 612 permits writings to refresh a witness's present memory, with safeguards for the other party."},{"id":"E-17-A","subject":"Evidence","topic":"Attorney-client privilege","type":"application","question":"A client privately confides facts to an attorney solely to obtain legal advice. Which privilege may apply?","options":["Attorney-client privilege","Confrontation Clause","Rule 404(b) other acts","Habit evidence"],"answer":0,"explanation":"Attorney-client privilege: Confidential communications made to obtain or provide legal advice generally may be privileged."},{"id":"E-17-B","subject":"Evidence","topic":"Attorney-client privilege","type":"rule","question":"Which statement correctly describes Attorney-client privilege?","options":["Testimonial hearsay normally cannot be admitted against a criminal defendant without unavailability and a prior opportunity for cross-examination.","Confidential communications made to obtain or provide legal advice generally may be privileged.","Other acts may be admissible for a legitimate nonpropensity use, subject to other limits.","A person's regular response to a specific repeated situation can be admissible as habit evidence."],"answer":1,"explanation":"Attorney-client privilege: Confidential communications made to obtain or provide legal advice generally may be privileged."},{"id":"E-18-A","subject":"Evidence","topic":"Lay opinion testimony","type":"application","question":"A neighbor testifies that a car sounded unusually loud, based on hearing it. Which opinion rule applies?","options":["Excited utterance","Business records","Character propensity prohibition","Lay opinion testimony"],"answer":3,"explanation":"Lay opinion testimony: Lay opinion may be based on personal perception if helpful and not based on specialized expertise."},{"id":"E-18-B","subject":"Evidence","topic":"Lay opinion testimony","type":"rule","question":"Which statement correctly describes Lay opinion testimony?","options":["Character evidence generally cannot prove conduct in conformity with a trait on a particular occasion, subject to exceptions.","Qualifying records of regularly conducted activity may be admitted under Rule 803(6) with proper foundation.","An excited utterance relates to a startling event while the speaker remains under its stress.","Lay opinion may be based on personal perception if helpful and not based on specialized expertise."],"answer":3,"explanation":"Lay opinion testimony: Lay opinion may be based on personal perception if helpful and not based on specialized expertise."},{"id":"E-19-A","subject":"Evidence","topic":"Expert reliability screening","type":"application","question":"An expert offers a scientific conclusion based on unreliable methods. Which admissibility rule applies?","options":["Hearsay definition","Rule 404(b) other acts","Expert reliability screening","Refreshing recollection"],"answer":2,"explanation":"Expert reliability screening: Rule 702 requires helpful expert testimony supported by sufficient facts, reliable methods, and reliable application."},{"id":"E-19-B","subject":"Evidence","topic":"Expert reliability screening","type":"rule","question":"Which statement correctly describes Expert reliability screening?","options":["Rule 612 permits writings to refresh a witness's present memory, with safeguards for the other party.","Rule 702 requires helpful expert testimony supported by sufficient facts, reliable methods, and reliable application.","Other acts may be admissible for a legitimate nonpropensity use, subject to other limits.","Hearsay is generally an out-of-court statement offered to prove the truth of its assertion."],"answer":1,"explanation":"Expert reliability screening: Rule 702 requires helpful expert testimony supported by sufficient facts, reliable methods, and reliable application."},{"id":"E-20-A","subject":"Evidence","topic":"Confrontation Clause","type":"application","question":"A testimonial police interview is offered against a criminal defendant without a chance to cross-examine its absent speaker. What protection applies?","options":["Prior inconsistent sworn statement","Excited utterance","Confrontation Clause","Recorded recollection"],"answer":2,"explanation":"Confrontation Clause: Testimonial hearsay normally cannot be admitted against a criminal defendant without unavailability and a prior opportunity for cross-examination."},{"id":"E-20-B","subject":"Evidence","topic":"Confrontation Clause","type":"rule","question":"Which statement correctly describes Confrontation Clause?","options":["An excited utterance relates to a startling event while the speaker remains under its stress.","Rule 803(5) allows qualifying recorded recollection to be read into evidence when its foundation is met.","Testimonial hearsay normally cannot be admitted against a criminal defendant without unavailability and a prior opportunity for cross-examination.","A prior inconsistent statement given under oath at a trial, hearing, or deposition can be substantive nonhearsay."],"answer":2,"explanation":"Confrontation Clause: Testimonial hearsay normally cannot be admitted against a criminal defendant without unavailability and a prior opportunity for cross-examination."},{"id":"RP-01-A","subject":"Real Property","topic":"Adverse possession","type":"application","question":"A possessor occupies another's land openly, notoriously, continuously, exclusively, and adversely for the legal period. Which doctrine may award title?","options":["Race recording statute","Adverse possession","Inquiry notice","Fee simple determinable"],"answer":1,"explanation":"Adverse possession: Adverse possession requires the statutory period and applicable elements of actual, open, exclusive, continuous hostile possession."},{"id":"RP-01-B","subject":"Real Property","topic":"Adverse possession","type":"rule","question":"Which statement correctly describes Adverse possession?","options":["Visible facts can place a reasonable purchaser on inquiry, charging notice of what reasonable investigation reveals.","A pure race recording statute generally gives priority to the first to record, subject to statutory particulars.","A fee simple determinable automatically ends when its stated condition is violated, leaving a possibility of reverter.","Adverse possession requires the statutory period and applicable elements of actual, open, exclusive, continuous hostile possession."],"answer":3,"explanation":"Adverse possession: Adverse possession requires the statutory period and applicable elements of actual, open, exclusive, continuous hostile possession."},{"id":"RP-02-A","subject":"Real Property","topic":"Fee simple determinable","type":"application","question":"A deed grants land 'so long as it is used as a library,' with a possibility of reverter. What estate exists?","options":["Prescriptive easement","Fee simple determinable","Marketable title","Adverse possession"],"answer":1,"explanation":"Fee simple determinable: A fee simple determinable automatically ends when its stated condition is violated, leaving a possibility of reverter."},{"id":"RP-02-B","subject":"Real Property","topic":"Fee simple determinable","type":"rule","question":"Which statement correctly describes Fee simple determinable?","options":["A land-sale contract ordinarily implies an obligation to deliver marketable title at closing, absent variation.","A fee simple determinable automatically ends when its stated condition is violated, leaving a possibility of reverter.","A prescriptive easement arises from qualifying open, notorious, adverse, continuous use for the statutory period.","Adverse possession requires the statutory period and applicable elements of actual, open, exclusive, continuous hostile possession."],"answer":1,"explanation":"Fee simple determinable: A fee simple determinable automatically ends when its stated condition is violated, leaving a possibility of reverter."},{"id":"RP-03-A","subject":"Real Property","topic":"Life estate","type":"application","question":"A grant transfers a home to Maya for life and then to Jordan. What estate does Maya hold?","options":["Prescriptive easement","Appurtenant easement","Life estate","Constructive eviction"],"answer":2,"explanation":"Life estate: A life estate lasts for the duration of the measuring life, after which a remainder or reversion takes possession."},{"id":"RP-03-B","subject":"Real Property","topic":"Life estate","type":"rule","question":"Which statement correctly describes Life estate?","options":["Constructive eviction may arise from substantial landlord-caused interference followed by timely vacation.","A life estate lasts for the duration of the measuring life, after which a remainder or reversion takes possession.","An appurtenant easement benefits dominant land and burdens servient land.","A prescriptive easement arises from qualifying open, notorious, adverse, continuous use for the statutory period."],"answer":1,"explanation":"Life estate: A life estate lasts for the duration of the measuring life, after which a remainder or reversion takes possession."},{"id":"RP-04-A","subject":"Real Property","topic":"Waste","type":"application","question":"A life tenant intentionally destroys permanent improvements, harming the remainderman. What doctrine applies?","options":["Race recording statute","Life estate","Inquiry notice","Waste"],"answer":3,"explanation":"Waste: Life tenants must avoid legally prohibited waste that harms holders of future interests."},{"id":"RP-04-B","subject":"Real Property","topic":"Waste","type":"rule","question":"Which statement correctly describes Waste?","options":["A pure race recording statute generally gives priority to the first to record, subject to statutory particulars.","A life estate lasts for the duration of the measuring life, after which a remainder or reversion takes possession.","Life tenants must avoid legally prohibited waste that harms holders of future interests.","Visible facts can place a reasonable purchaser on inquiry, charging notice of what reasonable investigation reveals."],"answer":2,"explanation":"Waste: Life tenants must avoid legally prohibited waste that harms holders of future interests."},{"id":"RP-05-A","subject":"Real Property","topic":"Joint-tenancy severance","type":"application","question":"One joint tenant conveys her full share to a stranger during life. What happens to that share's survivorship?","options":["Adverse possession","Appurtenant easement","Joint-tenancy severance","Prescriptive easement"],"answer":2,"explanation":"Joint-tenancy severance: An inter vivos conveyance generally severs the joint tenancy as to the conveyed interest."},{"id":"RP-05-B","subject":"Real Property","topic":"Joint-tenancy severance","type":"rule","question":"Which statement correctly describes Joint-tenancy severance?","options":["An appurtenant easement benefits dominant land and burdens servient land.","An inter vivos conveyance generally severs the joint tenancy as to the conveyed interest.","Adverse possession requires the statutory period and applicable elements of actual, open, exclusive, continuous hostile possession.","A prescriptive easement arises from qualifying open, notorious, adverse, continuous use for the statutory period."],"answer":1,"explanation":"Joint-tenancy severance: An inter vivos conveyance generally severs the joint tenancy as to the conveyed interest."},{"id":"RP-06-A","subject":"Real Property","topic":"Tenancy in common","type":"application","question":"One of two tenants in common dies leaving a will. How does the deceased owner's share pass?","options":["Waste","Tenancy in common","Constructive eviction","Adverse possession"],"answer":1,"explanation":"Tenancy in common: Tenancy in common has no survivorship; an owner's share descends to heirs or devisees."},{"id":"RP-06-B","subject":"Real Property","topic":"Tenancy in common","type":"rule","question":"Which statement correctly describes Tenancy in common?","options":["Life tenants must avoid legally prohibited waste that harms holders of future interests.","Adverse possession requires the statutory period and applicable elements of actual, open, exclusive, continuous hostile possession.","Constructive eviction may arise from substantial landlord-caused interference followed by timely vacation.","Tenancy in common has no survivorship; an owner's share descends to heirs or devisees."],"answer":3,"explanation":"Tenancy in common: Tenancy in common has no survivorship; an owner's share descends to heirs or devisees."},{"id":"RP-07-A","subject":"Real Property","topic":"Race recording statute","type":"application","question":"A land purchaser records first in a pure race jurisdiction although aware of a competing conveyance. Which rule governs priority?","options":["Tenancy in common","Race recording statute","Easement by necessity","Waste"],"answer":1,"explanation":"Race recording statute: A pure race recording statute generally gives priority to the first to record, subject to statutory particulars."},{"id":"RP-07-B","subject":"Real Property","topic":"Race recording statute","type":"rule","question":"Which statement correctly describes Race recording statute?","options":["Life tenants must avoid legally prohibited waste that harms holders of future interests.","Tenancy in common has no survivorship; an owner's share descends to heirs or devisees.","An easement by necessity can arise from severance of commonly owned land creating necessary access.","A pure race recording statute generally gives priority to the first to record, subject to statutory particulars."],"answer":3,"explanation":"Race recording statute: A pure race recording statute generally gives priority to the first to record, subject to statutory particulars."},{"id":"RP-08-A","subject":"Real Property","topic":"Notice recording statute","type":"application","question":"A later buyer pays value without notice of an earlier unrecorded deed in a notice jurisdiction. What protection applies?","options":["Inquiry notice","Easement by necessity","Prescriptive easement","Notice recording statute"],"answer":3,"explanation":"Notice recording statute: A notice statute generally protects a subsequent bona fide purchaser who lacked notice of the prior interest."},{"id":"RP-08-B","subject":"Real Property","topic":"Notice recording statute","type":"rule","question":"Which statement correctly describes Notice recording statute?","options":["An easement by necessity can arise from severance of commonly owned land creating necessary access.","A prescriptive easement arises from qualifying open, notorious, adverse, continuous use for the statutory period.","Visible facts can place a reasonable purchaser on inquiry, charging notice of what reasonable investigation reveals.","A notice statute generally protects a subsequent bona fide purchaser who lacked notice of the prior interest."],"answer":3,"explanation":"Notice recording statute: A notice statute generally protects a subsequent bona fide purchaser who lacked notice of the prior interest."},{"id":"RP-09-A","subject":"Real Property","topic":"Race-notice recording statute","type":"application","question":"A later buyer pays value without notice and records before the earlier grantee. What rule may protect the buyer?","options":["Assignment of lease","Race-notice recording statute","Fee simple determinable","Notice recording statute"],"answer":1,"explanation":"Race-notice recording statute: A race-notice statute generally requires taking without notice and recording first."},{"id":"RP-09-B","subject":"Real Property","topic":"Race-notice recording statute","type":"rule","question":"Which statement correctly describes Race-notice recording statute?","options":["A race-notice statute generally requires taking without notice and recording first.","A fee simple determinable automatically ends when its stated condition is violated, leaving a possibility of reverter.","A notice statute generally protects a subsequent bona fide purchaser who lacked notice of the prior interest.","An assignment transfers the tenant's entire remaining leasehold interest; retaining a reversion generally creates a sublease."],"answer":0,"explanation":"Race-notice recording statute: A race-notice statute generally requires taking without notice and recording first."},{"id":"RP-10-A","subject":"Real Property","topic":"Inquiry notice","type":"application","question":"A buyer observes an obvious driveway used by neighbors but never investigates their rights. What type of notice may arise?","options":["Easement by necessity","Joint-tenancy severance","Inquiry notice","Assignment of lease"],"answer":2,"explanation":"Inquiry notice: Visible facts can place a reasonable purchaser on inquiry, charging notice of what reasonable investigation reveals."},{"id":"RP-10-B","subject":"Real Property","topic":"Inquiry notice","type":"rule","question":"Which statement correctly describes Inquiry notice?","options":["An inter vivos conveyance generally severs the joint tenancy as to the conveyed interest.","An easement by necessity can arise from severance of commonly owned land creating necessary access.","An assignment transfers the tenant's entire remaining leasehold interest; retaining a reversion generally creates a sublease.","Visible facts can place a reasonable purchaser on inquiry, charging notice of what reasonable investigation reveals."],"answer":3,"explanation":"Inquiry notice: Visible facts can place a reasonable purchaser on inquiry, charging notice of what reasonable investigation reveals."},{"id":"RP-11-A","subject":"Real Property","topic":"Easement by necessity","type":"application","question":"A landowner splits a tract leaving a parcel landlocked and without reasonable access. What easement may arise?","options":["Easement by necessity","Waste","Race recording statute","License"],"answer":0,"explanation":"Easement by necessity: An easement by necessity can arise from severance of commonly owned land creating necessary access."},{"id":"RP-11-B","subject":"Real Property","topic":"Easement by necessity","type":"rule","question":"Which statement correctly describes Easement by necessity?","options":["An easement by necessity can arise from severance of commonly owned land creating necessary access.","A pure race recording statute generally gives priority to the first to record, subject to statutory particulars.","Life tenants must avoid legally prohibited waste that harms holders of future interests.","A license is permission to use land, generally revocable unless an exception applies."],"answer":0,"explanation":"Easement by necessity: An easement by necessity can arise from severance of commonly owned land creating necessary access."},{"id":"RP-12-A","subject":"Real Property","topic":"Prescriptive easement","type":"application","question":"A neighbor openly and adversely uses a path continuously for the statutory period. Which doctrine may create use rights?","options":["Prescriptive easement","Life estate","Race recording statute","Race-notice recording statute"],"answer":0,"explanation":"Prescriptive easement: A prescriptive easement arises from qualifying open, notorious, adverse, continuous use for the statutory period."},{"id":"RP-12-B","subject":"Real Property","topic":"Prescriptive easement","type":"rule","question":"Which statement correctly describes Prescriptive easement?","options":["A race-notice statute generally requires taking without notice and recording first.","A prescriptive easement arises from qualifying open, notorious, adverse, continuous use for the statutory period.","A pure race recording statute generally gives priority to the first to record, subject to statutory particulars.","A life estate lasts for the duration of the measuring life, after which a remainder or reversion takes possession."],"answer":1,"explanation":"Prescriptive easement: A prescriptive easement arises from qualifying open, notorious, adverse, continuous use for the statutory period."},{"id":"RP-13-A","subject":"Real Property","topic":"Appurtenant easement","type":"application","question":"A deed grants Lot A a right of way across Lot B for access. What estate benefits from the easement?","options":["Assignment of lease","Equitable servitude","Appurtenant easement","License"],"answer":2,"explanation":"Appurtenant easement: An appurtenant easement benefits dominant land and burdens servient land."},{"id":"RP-13-B","subject":"Real Property","topic":"Appurtenant easement","type":"rule","question":"Which statement correctly describes Appurtenant easement?","options":["An appurtenant easement benefits dominant land and burdens servient land.","A valid equitable servitude may be enforced in equity against successors with notice, subject to requirements.","A license is permission to use land, generally revocable unless an exception applies.","An assignment transfers the tenant's entire remaining leasehold interest; retaining a reversion generally creates a sublease."],"answer":0,"explanation":"Appurtenant easement: An appurtenant easement benefits dominant land and burdens servient land."},{"id":"RP-14-A","subject":"Real Property","topic":"License","type":"application","question":"An owner gives a friend permission to park for a weekend without creating an estate in land. What right is granted?","options":["Assignment of lease","License","Implied warranty of habitability","Life estate"],"answer":1,"explanation":"License: A license is permission to use land, generally revocable unless an exception applies."},{"id":"RP-14-B","subject":"Real Property","topic":"License","type":"rule","question":"Which statement correctly describes License?","options":["A life estate lasts for the duration of the measuring life, after which a remainder or reversion takes possession.","Residential leases often include a nonwaivable implied warranty of habitability, depending on law.","An assignment transfers the tenant's entire remaining leasehold interest; retaining a reversion generally creates a sublease.","A license is permission to use land, generally revocable unless an exception applies."],"answer":3,"explanation":"License: A license is permission to use land, generally revocable unless an exception applies."},{"id":"RP-15-A","subject":"Real Property","topic":"Equitable servitude","type":"application","question":"A buyer with notice of a valid subdivision restriction violates it, and a neighbor seeks an injunction. What doctrine applies?","options":["Equitable servitude","Inquiry notice","Joint-tenancy severance","Prescriptive easement"],"answer":0,"explanation":"Equitable servitude: A valid equitable servitude may be enforced in equity against successors with notice, subject to requirements."},{"id":"RP-15-B","subject":"Real Property","topic":"Equitable servitude","type":"rule","question":"Which statement correctly describes Equitable servitude?","options":["An inter vivos conveyance generally severs the joint tenancy as to the conveyed interest.","A valid equitable servitude may be enforced in equity against successors with notice, subject to requirements.","A prescriptive easement arises from qualifying open, notorious, adverse, continuous use for the statutory period.","Visible facts can place a reasonable purchaser on inquiry, charging notice of what reasonable investigation reveals."],"answer":1,"explanation":"Equitable servitude: A valid equitable servitude may be enforced in equity against successors with notice, subject to requirements."},{"id":"RP-16-A","subject":"Real Property","topic":"Implied warranty of habitability","type":"application","question":"An apartment's serious, unsafe defects make it unfit to live in despite a lease disclaimer. Which protection may apply?","options":["Delivery of deed","Implied warranty of habitability","Adverse possession","Prescriptive easement"],"answer":1,"explanation":"Implied warranty of habitability: Residential leases often include a nonwaivable implied warranty of habitability, depending on law."},{"id":"RP-16-B","subject":"Real Property","topic":"Implied warranty of habitability","type":"rule","question":"Which statement correctly describes Implied warranty of habitability?","options":["Residential leases often include a nonwaivable implied warranty of habitability, depending on law.","A prescriptive easement arises from qualifying open, notorious, adverse, continuous use for the statutory period.","Deed delivery requires intent for the conveyance to take present legal effect, not mere signature.","Adverse possession requires the statutory period and applicable elements of actual, open, exclusive, continuous hostile possession."],"answer":0,"explanation":"Implied warranty of habitability: Residential leases often include a nonwaivable implied warranty of habitability, depending on law."},{"id":"RP-17-A","subject":"Real Property","topic":"Assignment of lease","type":"application","question":"A tenant transfers the entire remainder of the leasehold term to another renter. What type of transfer is this?","options":["License","Race-notice recording statute","Equitable servitude","Assignment of lease"],"answer":3,"explanation":"Assignment of lease: An assignment transfers the tenant's entire remaining leasehold interest; retaining a reversion generally creates a sublease."},{"id":"RP-17-B","subject":"Real Property","topic":"Assignment of lease","type":"rule","question":"Which statement correctly describes Assignment of lease?","options":["A race-notice statute generally requires taking without notice and recording first.","An assignment transfers the tenant's entire remaining leasehold interest; retaining a reversion generally creates a sublease.","A valid equitable servitude may be enforced in equity against successors with notice, subject to requirements.","A license is permission to use land, generally revocable unless an exception applies."],"answer":1,"explanation":"Assignment of lease: An assignment transfers the tenant's entire remaining leasehold interest; retaining a reversion generally creates a sublease."},{"id":"RP-18-A","subject":"Real Property","topic":"Constructive eviction","type":"application","question":"A landlord's material interference forces a tenant to vacate after notice and reasonable time to cure. What doctrine applies?","options":["Appurtenant easement","Tenancy in common","Constructive eviction","Equitable servitude"],"answer":2,"explanation":"Constructive eviction: Constructive eviction may arise from substantial landlord-caused interference followed by timely vacation."},{"id":"RP-18-B","subject":"Real Property","topic":"Constructive eviction","type":"rule","question":"Which statement correctly describes Constructive eviction?","options":["Constructive eviction may arise from substantial landlord-caused interference followed by timely vacation.","A valid equitable servitude may be enforced in equity against successors with notice, subject to requirements.","Tenancy in common has no survivorship; an owner's share descends to heirs or devisees.","An appurtenant easement benefits dominant land and burdens servient land."],"answer":0,"explanation":"Constructive eviction: Constructive eviction may arise from substantial landlord-caused interference followed by timely vacation."},{"id":"RP-19-A","subject":"Real Property","topic":"Marketable title","type":"application","question":"A seller cannot convey reasonably defect-free title at closing under a land-sale contract. Which duty may be breached?","options":["Joint-tenancy severance","Constructive eviction","Prescriptive easement","Marketable title"],"answer":3,"explanation":"Marketable title: A land-sale contract ordinarily implies an obligation to deliver marketable title at closing, absent variation."},{"id":"RP-19-B","subject":"Real Property","topic":"Marketable title","type":"rule","question":"Which statement correctly describes Marketable title?","options":["An inter vivos conveyance generally severs the joint tenancy as to the conveyed interest.","Constructive eviction may arise from substantial landlord-caused interference followed by timely vacation.","A prescriptive easement arises from qualifying open, notorious, adverse, continuous use for the statutory period.","A land-sale contract ordinarily implies an obligation to deliver marketable title at closing, absent variation."],"answer":3,"explanation":"Marketable title: A land-sale contract ordinarily implies an obligation to deliver marketable title at closing, absent variation."},{"id":"RP-20-A","subject":"Real Property","topic":"Delivery of deed","type":"application","question":"A grantor signs a deed but keeps it without intending it to take present effect. What requirement is missing?","options":["Marketable title","Delivery of deed","Race-notice recording statute","Notice recording statute"],"answer":1,"explanation":"Delivery of deed: Deed delivery requires intent for the conveyance to take present legal effect, not mere signature."},{"id":"RP-20-B","subject":"Real Property","topic":"Delivery of deed","type":"rule","question":"Which statement correctly describes Delivery of deed?","options":["A notice statute generally protects a subsequent bona fide purchaser who lacked notice of the prior interest.","Deed delivery requires intent for the conveyance to take present legal effect, not mere signature.","A land-sale contract ordinarily implies an obligation to deliver marketable title at closing, absent variation.","A race-notice statute generally requires taking without notice and recording first."],"answer":1,"explanation":"Delivery of deed: Deed delivery requires intent for the conveyance to take present legal effect, not mere signature."},{"id":"T-01-A","subject":"Torts","topic":"Battery","type":"application","question":"A person deliberately makes harmful or offensive unconsented physical contact. What intentional tort applies?","options":["But-for causation","Battery","Self-defense privilege","Proximate causation"],"answer":1,"explanation":"Battery: Battery involves intentional harmful or offensive contact with another person."},{"id":"T-01-B","subject":"Torts","topic":"Battery","type":"rule","question":"Which statement correctly describes Battery?","options":["Reasonably necessary proportionate force against imminent unlawful force may be privileged as self-defense.","Actual causation is often shown if the harm would not have happened but for the defendant's conduct.","Proximate cause usually limits liability to harms within the foreseeable risks created by the negligence.","Battery involves intentional harmful or offensive contact with another person."],"answer":3,"explanation":"Battery: Battery involves intentional harmful or offensive contact with another person."},{"id":"T-02-A","subject":"Torts","topic":"Assault","type":"application","question":"A person raises a fist causing reasonable apprehension of immediate harmful contact but does not touch anyone. What tort applies?","options":["False imprisonment","Respondeat superior","Assault","Battery"],"answer":2,"explanation":"Assault: Assault involves an intentional act causing reasonable apprehension of imminent harmful or offensive contact."},{"id":"T-02-B","subject":"Torts","topic":"Assault","type":"rule","question":"Which statement correctly describes Assault?","options":["False imprisonment is intentional confinement within boundaries without lawful privilege, with awareness or harm.","Employers are often liable for torts of employees acting within the scope of employment.","Assault involves an intentional act causing reasonable apprehension of imminent harmful or offensive contact.","Battery involves intentional harmful or offensive contact with another person."],"answer":2,"explanation":"Assault: Assault involves an intentional act causing reasonable apprehension of imminent harmful or offensive contact."},{"id":"T-03-A","subject":"Torts","topic":"False imprisonment","type":"application","question":"A guard unlawfully locks a shopper in a room, and the shopper knows she cannot leave. What tort applies?","options":["Respondeat superior","Pure comparative negligence","Defamation actual malice","False imprisonment"],"answer":3,"explanation":"False imprisonment: False imprisonment is intentional confinement within boundaries without lawful privilege, with awareness or harm."},{"id":"T-03-B","subject":"Torts","topic":"False imprisonment","type":"rule","question":"Which statement correctly describes False imprisonment?","options":["Pure comparative negligence reduces recovery by the plaintiff's proportionate responsibility.","Employers are often liable for torts of employees acting within the scope of employment.","False imprisonment is intentional confinement within boundaries without lawful privilege, with awareness or harm.","A public official generally must prove knowledge of falsity or reckless disregard for truth for such defamation."],"answer":2,"explanation":"False imprisonment: False imprisonment is intentional confinement within boundaries without lawful privilege, with awareness or harm."},{"id":"T-04-A","subject":"Torts","topic":"Intentional infliction of emotional distress","type":"application","question":"A person intentionally engages in extreme and outrageous conduct causing severe emotional distress. What tort applies?","options":["Intentional infliction of emotional distress","Negligence breach","Negligence duty","Pure comparative negligence"],"answer":0,"explanation":"Intentional infliction of emotional distress: IIED generally requires extreme and outrageous conduct intentionally or recklessly causing severe emotional distress."},{"id":"T-04-B","subject":"Torts","topic":"Intentional infliction of emotional distress","type":"rule","question":"Which statement correctly describes Intentional infliction of emotional distress?","options":["Negligence ordinarily requires a duty of reasonable care toward those within the scope of that duty.","IIED generally requires extreme and outrageous conduct intentionally or recklessly causing severe emotional distress.","Pure comparative negligence reduces recovery by the plaintiff's proportionate responsibility.","Breach occurs when a person's conduct falls below the applicable standard of care."],"answer":1,"explanation":"Intentional infliction of emotional distress: IIED generally requires extreme and outrageous conduct intentionally or recklessly causing severe emotional distress."},{"id":"T-05-A","subject":"Torts","topic":"Trespass to land","type":"application","question":"A neighbor intentionally walks into another's fenced yard without permission. What tort can arise without actual damage?","options":["Manufacturing defect","Abnormally dangerous activity","Trespass to land","Conversion"],"answer":2,"explanation":"Trespass to land: Intentional unauthorized entry onto another's land is trespass even without major property damage."},{"id":"T-05-B","subject":"Torts","topic":"Trespass to land","type":"rule","question":"Which statement correctly describes Trespass to land?","options":["Conversion involves sufficiently serious intentional interference with another's possessory rights in personal property.","Intentional unauthorized entry onto another's land is trespass even without major property damage.","Abnormally dangerous activities can lead to strict liability for injuries resulting from their characteristic risks.","A manufacturing defect occurs when a product departs from intended design, even if the producer was careful."],"answer":1,"explanation":"Trespass to land: Intentional unauthorized entry onto another's land is trespass even without major property damage."},{"id":"T-06-A","subject":"Torts","topic":"Trespass to chattels","type":"application","question":"A person temporarily interferes with another's bicycle and causes measurable loss of use but no serious deprivation. What tort fits?","options":["Res ipsa loquitur","Trespass to chattels","Trespass to land","Respondeat superior"],"answer":1,"explanation":"Trespass to chattels: Trespass to chattels covers intentional interference causing dispossession or legally significant harm to personal property."},{"id":"T-06-B","subject":"Torts","topic":"Trespass to chattels","type":"rule","question":"Which statement correctly describes Trespass to chattels?","options":["Intentional unauthorized entry onto another's land is trespass even without major property damage.","Employers are often liable for torts of employees acting within the scope of employment.","Trespass to chattels covers intentional interference causing dispossession or legally significant harm to personal property.","Res ipsa may permit an inference of negligence when an accident ordinarily suggests negligence and defendant's control."],"answer":2,"explanation":"Trespass to chattels: Trespass to chattels covers intentional interference causing dispossession or legally significant harm to personal property."},{"id":"T-07-A","subject":"Torts","topic":"Conversion","type":"application","question":"A person intentionally sells another's rare painting, permanently depriving its owner of possession. What tort fits?","options":["Res ipsa loquitur","Negligence breach","Battery","Conversion"],"answer":3,"explanation":"Conversion: Conversion involves sufficiently serious intentional interference with another's possessory rights in personal property."},{"id":"T-07-B","subject":"Torts","topic":"Conversion","type":"rule","question":"Which statement correctly describes Conversion?","options":["Conversion involves sufficiently serious intentional interference with another's possessory rights in personal property.","Battery involves intentional harmful or offensive contact with another person.","Res ipsa may permit an inference of negligence when an accident ordinarily suggests negligence and defendant's control.","Breach occurs when a person's conduct falls below the applicable standard of care."],"answer":0,"explanation":"Conversion: Conversion involves sufficiently serious intentional interference with another's possessory rights in personal property."},{"id":"T-08-A","subject":"Torts","topic":"Self-defense privilege","type":"application","question":"A person uses proportional nondeadly force to stop an imminent unlawful attack. Which privilege may apply?","options":["Negligence per se","Respondeat superior","Contributory negligence","Self-defense privilege"],"answer":3,"explanation":"Self-defense privilege: Reasonably necessary proportionate force against imminent unlawful force may be privileged as self-defense."},{"id":"T-08-B","subject":"Torts","topic":"Self-defense privilege","type":"rule","question":"Which statement correctly describes Self-defense privilege?","options":["Reasonably necessary proportionate force against imminent unlawful force may be privileged as self-defense.","Negligence per se may apply when a safety statute protects the relevant class against the harm that occurred.","Employers are often liable for torts of employees acting within the scope of employment.","Pure contributory negligence may bar negligence recovery if the plaintiff's negligence contributed, with exceptions."],"answer":0,"explanation":"Self-defense privilege: Reasonably necessary proportionate force against imminent unlawful force may be privileged as self-defense."},{"id":"T-09-A","subject":"Torts","topic":"Negligence duty","type":"application","question":"A driver owes reasonable care to foreseeable pedestrians in a crosswalk. Which negligence element is illustrated?","options":["Pure comparative negligence","Negligence duty","Manufacturing defect","Trespass to land"],"answer":1,"explanation":"Negligence duty: Negligence ordinarily requires a duty of reasonable care toward those within the scope of that duty."},{"id":"T-09-B","subject":"Torts","topic":"Negligence duty","type":"rule","question":"Which statement correctly describes Negligence duty?","options":["Pure comparative negligence reduces recovery by the plaintiff's proportionate responsibility.","A manufacturing defect occurs when a product departs from intended design, even if the producer was careful.","Negligence ordinarily requires a duty of reasonable care toward those within the scope of that duty.","Intentional unauthorized entry onto another's land is trespass even without major property damage."],"answer":2,"explanation":"Negligence duty: Negligence ordinarily requires a duty of reasonable care toward those within the scope of that duty."},{"id":"T-10-A","subject":"Torts","topic":"Negligence breach","type":"application","question":"A motorist texts while driving and misses an obvious stop sign. Which negligence element is implicated?","options":["Negligence breach","Pure comparative negligence","Abnormally dangerous activity","Trespass to land"],"answer":0,"explanation":"Negligence breach: Breach occurs when a person's conduct falls below the applicable standard of care."},{"id":"T-10-B","subject":"Torts","topic":"Negligence breach","type":"rule","question":"Which statement correctly describes Negligence breach?","options":["Abnormally dangerous activities can lead to strict liability for injuries resulting from their characteristic risks.","Pure comparative negligence reduces recovery by the plaintiff's proportionate responsibility.","Intentional unauthorized entry onto another's land is trespass even without major property damage.","Breach occurs when a person's conduct falls below the applicable standard of care."],"answer":3,"explanation":"Negligence breach: Breach occurs when a person's conduct falls below the applicable standard of care."},{"id":"T-11-A","subject":"Torts","topic":"But-for causation","type":"application","question":"A pedestrian would not have been struck if the driver had obeyed the traffic signal. What causation test fits?","options":["Manufacturing defect","Intentional infliction of emotional distress","But-for causation","Res ipsa loquitur"],"answer":2,"explanation":"But-for causation: Actual causation is often shown if the harm would not have happened but for the defendant's conduct."},{"id":"T-11-B","subject":"Torts","topic":"But-for causation","type":"rule","question":"Which statement correctly describes But-for causation?","options":["A manufacturing defect occurs when a product departs from intended design, even if the producer was careful.","Res ipsa may permit an inference of negligence when an accident ordinarily suggests negligence and defendant's control.","Actual causation is often shown if the harm would not have happened but for the defendant's conduct.","IIED generally requires extreme and outrageous conduct intentionally or recklessly causing severe emotional distress."],"answer":2,"explanation":"But-for causation: Actual causation is often shown if the harm would not have happened but for the defendant's conduct."},{"id":"T-12-A","subject":"Torts","topic":"Proximate causation","type":"application","question":"A negligently spilled oil slick causes a foreseeable nearby vehicle crash minutes later. What limits the scope of liability?","options":["Proximate causation","Negligence breach","Negligence duty","Manufacturing defect"],"answer":0,"explanation":"Proximate causation: Proximate cause usually limits liability to harms within the foreseeable risks created by the negligence."},{"id":"T-12-B","subject":"Torts","topic":"Proximate causation","type":"rule","question":"Which statement correctly describes Proximate causation?","options":["Negligence ordinarily requires a duty of reasonable care toward those within the scope of that duty.","Breach occurs when a person's conduct falls below the applicable standard of care.","A manufacturing defect occurs when a product departs from intended design, even if the producer was careful.","Proximate cause usually limits liability to harms within the foreseeable risks created by the negligence."],"answer":3,"explanation":"Proximate causation: Proximate cause usually limits liability to harms within the foreseeable risks created by the negligence."},{"id":"T-13-A","subject":"Torts","topic":"Negligence per se","type":"application","question":"A driver violates a headlight law meant to protect nighttime pedestrians and injures one in that way. What doctrine may establish breach?","options":["Negligence duty","Negligence per se","Conversion","Self-defense privilege"],"answer":1,"explanation":"Negligence per se: Negligence per se may apply when a safety statute protects the relevant class against the harm that occurred."},{"id":"T-13-B","subject":"Torts","topic":"Negligence per se","type":"rule","question":"Which statement correctly describes Negligence per se?","options":["Conversion involves sufficiently serious intentional interference with another's possessory rights in personal property.","Negligence per se may apply when a safety statute protects the relevant class against the harm that occurred.","Negligence ordinarily requires a duty of reasonable care toward those within the scope of that duty.","Reasonably necessary proportionate force against imminent unlawful force may be privileged as self-defense."],"answer":1,"explanation":"Negligence per se: Negligence per se may apply when a safety statute protects the relevant class against the harm that occurred."},{"id":"T-14-A","subject":"Torts","topic":"Res ipsa loquitur","type":"application","question":"A heavy barrel falls from a controlled warehouse window onto a passerby without an ordinary explanation. What inference applies?","options":["Res ipsa loquitur","Abnormally dangerous activity","Self-defense privilege","Negligence breach"],"answer":0,"explanation":"Res ipsa loquitur: Res ipsa may permit an inference of negligence when an accident ordinarily suggests negligence and defendant's control."},{"id":"T-14-B","subject":"Torts","topic":"Res ipsa loquitur","type":"rule","question":"Which statement correctly describes Res ipsa loquitur?","options":["Res ipsa may permit an inference of negligence when an accident ordinarily suggests negligence and defendant's control.","Abnormally dangerous activities can lead to strict liability for injuries resulting from their characteristic risks.","Breach occurs when a person's conduct falls below the applicable standard of care.","Reasonably necessary proportionate force against imminent unlawful force may be privileged as self-defense."],"answer":0,"explanation":"Res ipsa loquitur: Res ipsa may permit an inference of negligence when an accident ordinarily suggests negligence and defendant's control."},{"id":"T-15-A","subject":"Torts","topic":"Contributory negligence","type":"application","question":"A plaintiff partly causes injury in a pure contributory-negligence jurisdiction. What defense may bar recovery?","options":["Negligence breach","False imprisonment","Contributory negligence","Manufacturing defect"],"answer":2,"explanation":"Contributory negligence: Pure contributory negligence may bar negligence recovery if the plaintiff's negligence contributed, with exceptions."},{"id":"T-15-B","subject":"Torts","topic":"Contributory negligence","type":"rule","question":"Which statement correctly describes Contributory negligence?","options":["A manufacturing defect occurs when a product departs from intended design, even if the producer was careful.","Breach occurs when a person's conduct falls below the applicable standard of care.","False imprisonment is intentional confinement within boundaries without lawful privilege, with awareness or harm.","Pure contributory negligence may bar negligence recovery if the plaintiff's negligence contributed, with exceptions."],"answer":3,"explanation":"Contributory negligence: Pure contributory negligence may bar negligence recovery if the plaintiff's negligence contributed, with exceptions."},{"id":"T-16-A","subject":"Torts","topic":"Pure comparative negligence","type":"application","question":"A plaintiff is 30 percent responsible for $100,000 in proven negligence damages. Which doctrine reduces the award to $70,000?","options":["Pure comparative negligence","Trespass to land","But-for causation","Manufacturing defect"],"answer":0,"explanation":"Pure comparative negligence: Pure comparative negligence reduces recovery by the plaintiff's proportionate responsibility."},{"id":"T-16-B","subject":"Torts","topic":"Pure comparative negligence","type":"rule","question":"Which statement correctly describes Pure comparative negligence?","options":["Actual causation is often shown if the harm would not have happened but for the defendant's conduct.","A manufacturing defect occurs when a product departs from intended design, even if the producer was careful.","Intentional unauthorized entry onto another's land is trespass even without major property damage.","Pure comparative negligence reduces recovery by the plaintiff's proportionate responsibility."],"answer":3,"explanation":"Pure comparative negligence: Pure comparative negligence reduces recovery by the plaintiff's proportionate responsibility."},{"id":"T-17-A","subject":"Torts","topic":"Respondeat superior","type":"application","question":"A delivery employee negligently hits a customer while doing assigned deliveries. Who may be vicariously liable?","options":["Respondeat superior","Proximate causation","False imprisonment","Intentional infliction of emotional distress"],"answer":0,"explanation":"Respondeat superior: Employers are often liable for torts of employees acting within the scope of employment."},{"id":"T-17-B","subject":"Torts","topic":"Respondeat superior","type":"rule","question":"Which statement correctly describes Respondeat superior?","options":["False imprisonment is intentional confinement within boundaries without lawful privilege, with awareness or harm.","Proximate cause usually limits liability to harms within the foreseeable risks created by the negligence.","IIED generally requires extreme and outrageous conduct intentionally or recklessly causing severe emotional distress.","Employers are often liable for torts of employees acting within the scope of employment."],"answer":3,"explanation":"Respondeat superior: Employers are often liable for torts of employees acting within the scope of employment."},{"id":"T-18-A","subject":"Torts","topic":"Abnormally dangerous activity","type":"application","question":"A company maintains explosives creating serious risk despite utmost precautions. Which liability doctrine may apply?","options":["Abnormally dangerous activity","Battery","Respondeat superior","Contributory negligence"],"answer":0,"explanation":"Abnormally dangerous activity: Abnormally dangerous activities can lead to strict liability for injuries resulting from their characteristic risks."},{"id":"T-18-B","subject":"Torts","topic":"Abnormally dangerous activity","type":"rule","question":"Which statement correctly describes Abnormally dangerous activity?","options":["Battery involves intentional harmful or offensive contact with another person.","Abnormally dangerous activities can lead to strict liability for injuries resulting from their characteristic risks.","Employers are often liable for torts of employees acting within the scope of employment.","Pure contributory negligence may bar negligence recovery if the plaintiff's negligence contributed, with exceptions."],"answer":1,"explanation":"Abnormally dangerous activity: Abnormally dangerous activities can lead to strict liability for injuries resulting from their characteristic risks."},{"id":"T-19-A","subject":"Torts","topic":"Manufacturing defect","type":"application","question":"A sealed blender has a blade that deviates from the intended design and injures its user. What product-defect category applies?","options":["Trespass to chattels","Negligence per se","Res ipsa loquitur","Manufacturing defect"],"answer":3,"explanation":"Manufacturing defect: A manufacturing defect occurs when a product departs from intended design, even if the producer was careful."},{"id":"T-19-B","subject":"Torts","topic":"Manufacturing defect","type":"rule","question":"Which statement correctly describes Manufacturing defect?","options":["Trespass to chattels covers intentional interference causing dispossession or legally significant harm to personal property.","Negligence per se may apply when a safety statute protects the relevant class against the harm that occurred.","A manufacturing defect occurs when a product departs from intended design, even if the producer was careful.","Res ipsa may permit an inference of negligence when an accident ordinarily suggests negligence and defendant's control."],"answer":2,"explanation":"Manufacturing defect: A manufacturing defect occurs when a product departs from intended design, even if the producer was careful."},{"id":"T-20-A","subject":"Torts","topic":"Defamation actual malice","type":"application","question":"A public official sues over a false statement about official conduct. What constitutional standard applies?","options":["Abnormally dangerous activity","Assault","But-for causation","Defamation actual malice"],"answer":3,"explanation":"Defamation actual malice: A public official generally must prove knowledge of falsity or reckless disregard for truth for such defamation."},{"id":"T-20-B","subject":"Torts","topic":"Defamation actual malice","type":"rule","question":"Which statement correctly describes Defamation actual malice?","options":["Actual causation is often shown if the harm would not have happened but for the defendant's conduct.","Assault involves an intentional act causing reasonable apprehension of imminent harmful or offensive contact.","A public official generally must prove knowledge of falsity or reckless disregard for truth for such defamation.","Abnormally dangerous activities can lead to strict liability for injuries resulting from their characteristic risks."],"answer":2,"explanation":"Defamation actual malice: A public official generally must prove knowledge of falsity or reckless disregard for truth for such defamation."}];
